  "高度通用，理解能力强，适合长对话及复杂推理任务，支持丰富的图像与工具交互。": "優れた総合パフォーマンスと高い理解力を備え、長時間の会話や複雑な推論、豊富な画像・ツール連携にも最適です。",
  "性价比高，适合快速响应的通用任务，处理高并发时表现优异。": "高いコスト効率を実現し、高並列環境でも優れたパフォーマンスを発揮します。迅速な一般業務にも最適です。",
  "超低延迟，适合小任务和边缘场景": "超低レイテンシーで、小規模なタスクやエッジシナリオに最適です",
  "稳健的通用模型，支持复杂工具操作和图像分析，适合多种高复杂度任务。": "高度なツールおよび画像解析に対応した、汎用性の高い堅牢なモデルです。複雑な業務に最適です。",
  "轻量级通用多模态模型，适合对速度与稳定性有高要求的日常任务。": "高速かつ安定した動作が求められる日常的な業務に適した、軽量な汎用マルチモーダルモデルです。",
  "支持文本、图像的多模态模型，适用于复杂推理和长对话任务。": "テキストと画像に対応したマルチモーダルモデルで、複雑な推論や長時間の対話にも最適です。",
  "高性价比的多模态模型，适合日常任务和轻度推理，响应速度快。": "日常業務や軽度な推論に最適なコスト効率を実現し、マルチモーダルな応答を高速で提供します。",
  "中型推理模型，支持多模态输入，适合一般推理任务和中等规模的数据处理。": "マルチモーダル入力に対応した中規模の推論モデルで、汎用的な推論や中規模処理に適しています。",
  "设计用于处理高并发任务，适合流量较大或需要快速响应的场景。": "高い同時実行ワークロード向けに設計されており、大量トラフィックや高速応答が求められるシナリオに適しています。",
  "小型推理优化版，适合成本敏感的多模态任务，适用于轻量级推理场景。": "コスト効率を重視したマルチモーダルタスクや軽量な推論シナリオ向けの推論最適化済みミニモデルです。",
  "专为文本生成任务设计，支持高效的工具调用，适合文本处理和对话场景。": "テキスト生成に特化し、効率的なツール利用が可能なモデルです。テキスト処理や会話に適しています。",
