  "生成一个现代科技风格的电子时钟，展示小时和分钟，用户可以分别设置小时与分钟，修改其中任意一个时，都将时间以\"00:00\"的格式保存。如果载入时有值，将值回显到时钟上显示。当组件参数 env 中的 isDisabled 为 true 时，禁止设置时钟，只能展示时间。": "現代的なデジタル時計を生成し、時と分を個別に設定できます。どちらかの値が変更されると、「00:00」形式で時刻を保存します。読み込み時に値が存在する場合は、その時刻を時計に表示します。コンポーネントパラメータ env.isDisabled が true の場合、編集を無効にし、時刻のみを表示します。",
