  "以上字段引用的数据之后如果发生变更，将不会自动更新，只能手动刷新。": "参照データは自動で更新されず、手動での更新のみ対応しています。",
  "单向关联：": "一方向リンク:",
  "仅在当前表维护关联关系": "現在のテーブル内でのみリレーションを保存します",
  "双向关联：": "双方向リンク",
  "什么是双向关联？": "双方向リンクとは何ですか？",
  "💡 适用于被高频引用的标签、省市区、费用科目等字典表。开启后，关联时不向目标表写入反向数据，从而提升表单性能。": "💡 タグや地域、経費区分など、高頻度で参照される辞書データに適しています。有効にすると、関連データが対象テーブルに書き戻されず、フォームのパフォーマンスが向上します。",
  "勾选后：": "有効化すると：",
  "- 汇总、他表字段（存储数据类型）不会自动更新，只能手动刷新。": "- サマリーおよび外部フィールド（保存済みデータ型）の値は手動で更新する必要があります。",
  "- 当关联的记录被删除时，不会自动取消关联，将显示为已删除。": "- 削除された関連レコードは、リンクされた状態のまま削除済みとして表示されます。",
  "建立双向关联": "双方向リンクを作成",
  "关联工作表": "関連ワークシート",
  "检测到有可建立的双向关联": "双方向リンクが利用可能です",
  "“%0”中存在可添加到当前工作表的反向字段，是否使用已有关系添加反向字段？关闭后将会创建一组新的关联关系。": "「%0」には、現在のワークシート用のリバースフィールドが利用可能です。既存のリンクを使用して追加しますか？オフにすると新しいリンクが作成されます。",
  "%0 中的已有关联关系": "%0 の既存リンク",
  "选择其他工作表中已关联 \"%0\" 的字段建立双向关联。建立后，可在两个工作表中维护同一关联关系": "別のワークシートで「%0」とリンクされたフィールドを選択すると、両方のワークシートから管理できる双方向リンクを作成できます。",
  "配置建议：": "セットアップのヒント",
  "如仅需在当前表中查看记录，可使用“查询记录”字段，无需创建双向关联。如：在客户表中查看关联当前客户的订单。": "現在のワークシート内のレコードのみを閲覧する場合は、「レコード検索」フィールドをご利用ください。新しく双方向リンクを作成する必要はありません。たとえば、「顧客」ワークシートで、その顧客に紐付く注文を閲覧する場合に便利です。",
  "如需在两个工作表中同时维护关联关系。如：项目与成员、用户与角色。则需创建为双向关联。": "プロジェクトとメンバー、またはユーザーとロールなど、両方のワークシートからリンクを管理するには、双方向リンクを作成してください。",
  "关联其他工作表中的记录，并保存记录之间的关系。如：订单关联客户。": "他のワークシートからレコードをリンクし、その関係性を保存します。たとえば、注文を顧客にリンクします。",
  "添加关联记录字段": "関連レコードフィールドを追加",
  "在当前表中存储数据，存储后他表字段可用于工作表搜索、筛选、排序、统计，或被公式、文本组合字段使用。": "現在のテーブルに保存した後、他のテーブルのフィールドを検索・フィルター・並べ替え・集計や、数式やテキスト結合フィールドで参照できます。",
  "当前关联记录已开启【轻量级单向关联】：当引用的数据源的字段变更后，不会同步更新本表的他表字段数据。": "軽量な一方向リンクが有効：ソースフィールドでの変更は、このフィールドに同期されなくなります。",
  "当前关联记录已开启【轻量级单向关联】，当引用的数据源字段变更后，不会同步更新本表的汇总字段数据": "軽量型の一方向リンクが有効になっています。ソースフィールドの変更は、今後このテーブルのサマリーフィールドと自動同期されません。",
  "未选择时，系统自动推荐": "未選択の場合は自動推奨します",
  "更多保存选项": "その他の保存オプション",
  "次数受限": "上限に達しました",
  "暂无可用的打印模板": "利用可能な印刷テンプレートがありません",
  "更多导入方式": "その他のインポートオプション",
  "反馈失败，请稍后重试": "フィードバックの送信に失敗しました。後ほど再度お試しください。",
  "关联方式": "リンクメソッド",
  "反馈使用中遇到的错误或提出改进意见": "問題の報告や改善案のご提案",
