  "反馈内容": "フィードバック内容",
  "所有接口": "すべてのインターフェース",
  "获取更多信息": "詳細はこちら",
  "获取人员的汇报关系信息": "メンバーの報告関係を取得",
  "包含人员的直属上司、直接下属、所有下属；无需汇报关系时建议取消勾选，提升查询效率": "本人の直属上司、直属の部下、およびすべての部下を含みます。レポート関係が不要な場合は、チェックを外すことでクエリ効率を向上できます。",
  "获取当前组织已集成的第三方用户 ID（企业微信/钉钉/飞书/Lark/Miacrosoft Entra）；无需第三方用户 ID时建议取消勾选，提升查询效率": "外部サービスのユーザーID（WeCom／DingTalk／Feishu／Lark／Microsoft Entra）を取得します。不要な場合はチェックを外すことで、クエリ効率が向上します。",
  "单次最多上传%0个图标": "一度に%0個までアイコンをアップロードできます",
  "无法获取补充资料，请重试或重新验证身份": "詳細情報の取得に失敗しました。再試行するか、再認証してください。",
  "重新验证": "再検証",
  "无法完成授权": "認可に失敗しました",
  "回调地址不是本机地址，可能是被伪造的授权链接，已阻止跳转。": "コールバックURLがローカルアドレスではなく、不正な認証リンクの可能性があります。リダイレクトはブロックされました。",
  "授权本地开发工具": "ローカル開発ツールを認証",
  "mdye-cli 将获得当前账号的登录凭证，用于在本地调试插件。请确认这次授权是你本人发起的。": "mdye-cliでプラグインをローカル環境でデバッグするためには、アカウント認証情報が必要です。ご自身でこの認証を開始したことを確認してください。",
  "当前账号：%0": "現在のアカウント：%0",
  "。需开通 Code 功能，并建议使用最新版客户端。": "。コード機能を有効にし、最新のクライアントバージョンへアップデートしてください。",
  "组织者": "オーガナイザー",
  "反馈入口暂未开放": "フィードバックエントリーはまだ利用できません。",
  "当前请求暂不可反馈": "フィードバックは現在ご利用いただけません",
  "反馈服务暂不可用，请稍后重试": "フィードバックサービスは一時的にご利用いただけません。しばらくしてから再度お試しください。",
  "打开反馈页面失败，请稍后重试": "フィードバックページを開くことができませんでした。後ほど再度お試しください。",
  "2.支付渠道：拉卡拉(费率0.3%)、微信支付/支付宝支付(费率以签约渠道为准)。": "2. 決済チャネル：Lakala（手数料率0.3%）、WeChat Pay／Alipay（各チャネル契約による手数料率）",
  "拉卡拉": "Lakala",
  "填写代理服务器的 IP 地址或域名，如 192.168.1.10 或 proxy.example.com，不包含 http://、https://": "プロキシサーバーのIPアドレスまたはドメイン名（例：192.168.1.10 や proxy.example.com）を入力してください。  \n「http://」や「https://」は含めないでください。",
  "由拉卡拉提供，暂时需要联系顾问线下申请商户入网；支持微信和支付宝聚合支付，费率固定为0.3%": "Lakalaが提供しています。加盟店の登録はコンサルタントによるオフライン申請が必要です。WeChatおよびAlipayの統合決済に対応しており、手数料率は一律0.3%です。",
  "请联系您的专属顾问协助完成商户入网": "加盟店のオンボーディングについては、専任コンサルタントまでご連絡ください。",
  "是指通过代理访问的目标 URL 的协议类型": "プロキシ経由でアクセスする対象URLのプロトコル種別を指します。",
  "文本组合%04000": "テキストの組み合わせ",
  "汇总关联记录或子表中的数据，如：汇总订单明细中的商品总价，最大支持汇总1000行数据。": "関連レコードやサブテーブルのデータを集計 例: 注文明細の合計金額 最大1000行まで",
  "将当前记录中的字段进行数值或日期计算": "現在のレコード内の項目で数値や日付の計算を行います",
  "在此添加 注意事项 或 填写要求 等，来指导使用者(或填写者)正确地操作": "ここに注意事項や記入要件を追加して、ユーザー（または記入者）が正しく操作するための指導を行ってください。",
  "把注意事项或填写要求作为“备注”加入，来指导使用者(或填写者)正确使用": "注意事項や記入要件を「備考」として追加し、利用者を正しく案内",
  "可通过定位输入地理位置": "位置を特定することで地理的位置を入力できます",
  "可控制文本样式，添加图片": "テキストスタイルを制御し、画像を追加する",
  "通过签名确定签名人身份": "署名で署名者の身元確認",
  "级联选择%04003": "カスケード選択",
  "以层级视图作为数据源来选择目标表的记录,仅支持本表关联": "階層ビューを使用して対象テーブルのレコードをデータソースとして選択できますが、本テーブルとの関連のみサポートされます。",
  "文本识别": "OCR",
  "识别输入图片，将识别结果填充到对应字段。": "入力画像を認識し、認識結果を対応するフィールドに入力します。",
  "在表单中添加说明信息": "ワークシートに説明情報を追加する",
  "嵌入%04010": "埋め込む",
  "在表单中嵌入URL，支持使用其他字段值传参": "フォームにURLを埋め込み他フィールド値でパラメータ指定可能",
  "可将关联的数据源转成条形码或二维码显示": "関連データをバーコード／QRコード表示にできます",
  "可设为小时分钟秒": "時間、分、秒として設定可能",
  "选择组织中的角色，支持配置选择的组织角色的权限。": "組織ロールを選択し、ロール権限の設定をサポートします",
  "可调用API接口获取数据，并将数据填充到字段。": "APIを利用してデータ取得しフィールドに反映",
