  "登录页背景图，推荐尺寸 1920*900，2 M以内": "ログインページの背景画像、推奨サイズ1920*900、2M以内",
  "当组织、用户信息变更时，以标准的 HTTP 协议把事件内容推送到指定的地址。请求时间超过10秒则超时，超时后不再重试。": "組織またはユーザー情報が変更されると、標準のHTTPプロトコルを使用して、イベント内容が指定されたアドレスにプッシュされます。リクエスト時間が10秒を超えるとタイムアウトとなり、タイムアウト後は再試行されません。",
