  "开启后，开放插件中心入口，且支持在系统内使用插件能力": "有効化すると、プラグインセンターの入口が開放され、システム内でプラグイン機能を使用できるようになります。",
  "允许非平台管理员创建组织（若禁用，仅平台管理员可创建组织）": "プラットフォーム管理者以外のユーザーが組織を作成できる（無効にすると、プラットフォーム管理者のみが組織を作成できます）",
