  "服务": "サービス",
  "%0个短信模版": "%0 SMS テンプレート",
  "短信服务": "ショートメッセージサービス（SMS）",
  "验证码短信": "認証コードSMS",
  "仅支持发送登录/注册验证码。只需配置一个服务商，若配置了多个服务商，则发送验证码短信时每次会随机选择一个。": "ログイン/登録の認証コードの送信のみをサポートします。サービスプロバイダーを1つ構成するだけで、複数のサービスプロバイダーが構成されている場合は、認証コードSMSを送信する際に毎回ランダムに1つが選択されます。",
  "自定义短信功能": "カスタムSMS機能",
  "开启后将显示短信相关功能入口（如：工作流发送短信节点、手机号邀请用户、外部门户短信通知等）。为保障功能实际可用，需要自行申请第三方短信服务商账号，然后自主集成或由官方技术团队定制开发": "オンにすると、SMS 関連機能への入り口が表示されます (SMS ノードを送信するワークフロー、携帯電話番号の招待ユーザー、外部ポータルの SMS 通知など)。この機能を実際に利用できるようにするには、サードパーティの SMS サービス プロバイダーのアカウントを申請して、それを個別に統合するか、公式の技術チームによってカスタマイズおよび開発してもらう必要があります。",
  "了解自主集成": "自主インテグレーションを理解する",
  "%0短信配置服务": "%0 SMS 構成サービス",
  "如果组织内不使用以下第三方平台，可取消勾选": "組織内で以下のサードパーティプラットフォームを使用しない場合は、チェックを外してください",
  "地图服务": "マップサービス",
  "开启后将显示地图相关功能入口（如：地图视图、定位字段、个人偏好设置>地图）。若要保证功能正常使用，还需要在下方配置并开启地图服务。个人偏好>地图的初始值将跟随列表中第一个开启的地图服务": "有効にすると、地図関連の機能エントリが表示されます（例：地図ビュー、位置情報フィールド、個人設定>地図）。機能が正常に使用されるようにするには、下にある地図サービスを設定して有効にする必要があります。個人設定>地図の初期値は、リストの最初に有効にされた地図サービスに従います。",
  "开启后将显示数据集成相关功能入口（如：数据集成、聚合表）": "有効にすると、データインテグレーションに関連する機能の入口が表示されます（例：データ統合、集約ワークシート）",
  "了解服务配置": "サービス設定を理解する",
  "手机号和邮箱至少选一项": "電話番号またはメールアドレスのいずれかを少なくとも1つ選択してください。",
  "协议 / 隐私条款": "契約 / プライバシーポリシー",
  "用户在注册、登录账号时，需要同意《服务协议》和《隐私政策》": "ユーザーはアカウントを登録またはログインする際に、「サービス契約」と「プライバシーポリシー」に同意する必要があります。",
  "用户注册时必须选择同意": "ユーザーは登録時に承認する必要があります",
  "单点登录时（Web移动端），也必须先同意": "シングルサインオンを使用する際（Webモバイル端末）、最初に同意する必要があります",
  "在法律门户中设置": "法律ポータルに設定する",
  "允许自注册账号": "アカウントのセルフ登録を許可する",
  "开启后，在登录页显示注册账号入口": "有効にすると、ログインページにアカウント登録の入口を表示します",
  "允许用户修改账号信息": "ユーザーがアカウント情報を修正できるようにする",
  "开启后，允许用户编辑个人账户中的姓名、邮箱、手机号": "有効化すると、ユーザーは個人アカウントの名前、メール、携帯電話番号を編集できます",
  "允许使用验证码登录": "確認コードでログインを許可",
  "开启时,支持使用短信或邮件验证码登录。为确保功能可用,须先集成短信、邮件服务": "有効にすると、SMSまたは電子メールの認証コードを使用してログインできます。機能を利用できるようにするには、SMSおよび電子メールサービスを統合する必要があります。",
  "开启后绑定邮箱或手机号时，需要验证合法性": "有効にした後にメールアドレスまたは電話番号をバインドする際、合法性の確認が必要です。",
