  "SSO自主集成": "SSO自主インテグレーション",
  "应用ID格式不正确，请重新输入": "アプリケーションIDの形式が正しくありません。再度入力してください。",
  "可自定义工作台显示的资源列表项": "作業スペースに表示されるリソースリスト項目をカスタマイズ可能",
  "是否开启两步验证 ?": "二段階認証を有効にしますか？",
  "开启后，除了基于账号密码的登录认证，还需要通过手机号或邮箱接收验证码进行二次认证，所以请确保组织成员的手机号、邮箱的合法性，同时确保系统内的短信服务、邮件服务已正常启用。": "開設後、アカウントパスワードによるログイン認証に加え、二次認証のために携帯電話番号またはメールアドレスを通じて認証コードを受け取る必要があるため、組織メンバーの携帯電話番号およびメールアドレスの正当性を確認し、システムのSMSサービスおよびメールサービスが正常に有効になっていることを確認してください。",
  "二次验证": "二段階認証",
  "二次验证方式优先级": "検証の優先順位",
  "此项为“登录二次验证”，开启后，除了基于账号密码的登录认证，还需要通过手机号或邮箱接收验证码进行二次认证，所以请确保组织成员的手机号、邮箱的合法性，同时确保系统内的短信服务、邮件服务已正常启用。": "これは「ログイン二重認証」です。有効にすると、ユーザー名とパスワードの認証に加えて、携帯電話番号またはメールアドレスで受信した確認コードによる二重認証が必要となります。したがって、組織メンバーの携帯電話番号とメールアドレスの合法性を確認し、システム内のSMSサービスとメールサービスが正常に有効になっていることを確認してください。",
  "登录时优先采用设置的验证方式进行验证": "ログイン時には設定された認証方法を優先して検証します",
  "不过期": "期限切れではない",
  "2天": "2日",
  "5天": "5日",
  "15天": "15日",
  "密码有效期": "パスワードの有効期限",
  "密码过期后，用户需设置新密码才能使用系统": "パスワードが期限切れになると、ユーザーはシステムを使用するために新しいパスワードを設定する必要があります",
  "首次登录需修改密码": "初回ログイン時にパスワードを変更する必要があります",
  "过期天数": "期限切れの日数",
  "在首次登录自主创建的账号、导入的预设账号、被管理员重置密码的账号时生效": "新規作成・インポート済み・管理者リセット後の初回ログイン時に有効です",
  "密码规则": "パスワードルール",
  "启用后，平台用户密码安全策略将按配置进行强校验": "有効にすると、プラットフォームのユーザーパスワードセキュリティポリシーは、設定に従って厳しく検証されます。",
  "开启时，平台账户可自行配置设备登录限制(账户管理-->安全设置)；关闭后，平台用户仅可在同设备类型登录一个终端，例如在Web浏览器登录后，将会使其他Web浏览器登录的同一账号强制退出登录，以确保账户登录安全，手机APP同理": "オンにすると、プラットフォームアカウントはデバイスログイン制限を自分自身で設定できます（アカウント管理 --> セキュリティ設定）；オフにすると、プラットフォームユーザーは同じデバイスタイプで1つの端末のみログインできます。たとえば、Webブラウザでログインすると、他のWebブラウザで同じアカウントがログインしている場合、そのアカウントは強制的にログアウトされ、アカウントのログインセキュリティが確保されます。モバイルAPPも同様です。",
  "提示说明": "通知の説明",
  "接口防护": "インターフェース保護",
  "平台中部分接口需在未鉴权的情况下被调用，如：全局固定的配置信息；关联表字段结构；对外公开分享、查询和填写等。如果需要接口严格鉴权或响应体加密返回，可开启此配置。": "プラットフォーム内の一部のインターフェースは、認証なしで呼び出す必要があります。例：グローバル固定の設定情報、関連テーブルフィールド構造、外部公開の共有、クエリおよび入力など。インターフェースに厳格な認証または暗号化されたレスポンスボディが必要な場合は、この設定を有効にできます。",
