  "组织管理员不允许使用个人访问令牌": "オーグの管理者はパーソナルアクセストークンを使用できません。",
  "个人访问令牌代表您的身份，用于 HAP 数据的操作访问。您可自定义权限范围和数据访问权限。️安全提示：令牌具有账户权限，请勿分享给他人。": "パーソナルアクセストークンは、お客様に代わってHAPデータへアクセスします。必要に応じてスコープやデータアクセスをカスタマイズできます。  \nヒント：トークンにはお客様のアカウント権限が付与されますので、安全に管理してください。",
  "5. 可通过代码 #{[qrcode]字段名$[20*20]$} 或 #{[barcode]字段名$[40*10]$} 获取任意字段的二维码 或 条形码。二维码编码方式：QR-code，最大包含150个字（支持汉字）；条形码编码方式：code128，最大包含30个字符（仅支持数字、字母、符号）。如需隐藏条形码下方的显示值字段，则增加_NT控制隐藏，例如 #{[barcode]字段名$[40*10_NT]$} 隐藏条形码下方文字；不加 _NT 仍按原逻辑显示。": "5. QRコードを表示する場合は #{[qrcode]FieldName$[20*20]$} をご利用ください（全角150文字以内、中国語を含む）。バーコードを表示する場合は #{[barcode]FieldName$[40*10]$} をご利用ください（半角英数字および記号で30文字以内）。バーコード下部のテキストを非表示にするには、_NTを追加してください（例：#{[barcode]FieldName$[40*10_NT]$}）。テキストを表示する場合は、_NTを省略してください。",
