  "其中「AI福利点」为每月平台赠送额度，仅抵扣AI搭建应用费用；使用用AI搭建应用时会优先消耗AI福利点，额度用尽后再从通用信用点扣费。": "AI無料クレジットは、AIエージェントアプリの利用料金に対する毎月の付与分です。アプリの構築時に優先して適用され、使い切った後はクレジット残高から料金が差し引かれます。",
