  "前端项目搭建 — 把明道云后端搭独立站点": "フロントエンドプロジェクトのセットアップ — Mingdaoバックエンドを単体サイトとしてデプロイ",
  "通过终端命令调用 HAP 能力，覆盖应用、工作表、工作流、审批、通讯录、日程、群聊等更多场景，适用于在本地终端、服务器脚本或自动化脚本中使用。必须安装 Python 环境（版本号 >= 3.10）。": "ターミナルコマンドを使用して、アプリ、ワークシート、ワークフロー、承認、連絡先、カレンダー、グループチャットなど、HAPの各種機能にアクセスできます。ローカル端末やサーバー、または自動化スクリプトに対応しています。Python 3.10以上が必要です。",
  "安装 Skills": "スキルをインストール",
  "让 AI 真正掌握操作 HAP 的能力，覆盖 CLI 命令、MCP 服务、API 接口三种使用方式，从建应用、改数据到二次开发全流程支持。": "AIがHAPの操作を完全に習得できるようにします。CLIコマンド、MCPサーバーのサービス、APIインターフェースを網羅しており、アプリ構築、データの変更、二次開発までの全プロセスをサポートします。",
