  "需组织管理员在「组织后台 - 数据与访问」中开启后才能使用": "オーガナイゼーション管理者が「オーグ管理」＞「データとアクセス」で有効にする必要があります。",
  "同时安装配套Skills": "インストール関連スキル",
  "平台强制开启两步验证": "2段階認証を強制する",
  "API 文档": "APIドキュメント",
  "5. 可通过代码 #{[qrcode]字段名$[20*20]$} 或 #{[barcode]字段名$[40*10]$} 获取任意字段的二维码或条形码。其中：[20*20]、[40*10] 表示二维码/条形码的宽高尺寸，单位为 mm；二维码编码方式为 QR-code，最大包含 150 个字，支持汉字；条形码编码方式为 code128，最大包含 30 个字符，仅支持数字、字母、符号。": "5. 「#{[qrcode]FieldName$[20*20]$}」または「#{[barcode]FieldName$[40*10]$}」を使用すると、QRコードまたはバーコードを生成できます。寸法は、[20*20]および[40*10]がmm単位です。QRコードは最大150文字（中国語を含む）まで対応し、QRコードエンコーディングを使用します。バーコードは最大30文字（数字、英字、記号）まで対応し、Code128エンコーディングを使用します。",
  "（1）二维码尺寸为固定尺寸。[20*20] 表示二维码宽高固定为 20*20。二维码需保持正方形显示，不支持 auto 自适应尺寸。": "(1) QRコードのサイズは20×20に固定されており、自動リサイズには対応していません。表示は正方形のみサポートします。",
  "（2）条形码尺寸支持 4 种设置方式。[40*auto] 表示宽度固定为 40，高度按比例自适应；[auto*10] 表示高度固定为 10，宽度按比例自适应；[40*10_auto] 表示宽高在 40*10 的范围内同时自适应；[40*10] 表示宽高为固定尺寸。": "(2) バーコードのサイズ設定は、以下の4つのモードから選択できます。\n- [40*auto]：幅40固定、高さは自動調整\n- [auto*10]：高さ10固定、幅は自動調整\n- [40*10_auto]：40×10の範囲内で自動調整\n- [40*10]：幅・高さともに固定",
  "（3）条形码默认显示下方文字。如需隐藏条形码下方的显示值，可增加 _NT 控制隐藏。例如：#{[barcode]字段名$[40*10_NT]$} 表示隐藏条形码下方文字；不加 _NT 仍按原逻辑显示。": "(3) 標準では、バーコードの下部にテキストが表示されます。テキストを非表示にするには、_NT を追加してください。例：#{[barcode]FieldName$[40*10_NT]$} ではテキストが非表示になります。_NT を省略するとテキストは表示されます。",
  "（4）示例代码：#{[qrcode]字段名$[20*20]$} 表示获取固定尺寸为 20*20 的二维码；#{[barcode]字段名$[40*auto]$} 表示条形码宽度固定为 40，高度按比例自适应；#{[barcode]字段名$[auto*10]$} 表示条形码高度固定为 10，宽度按比例自适应；#{[barcode]字段名$[40*10_NT]$} 表示获取固定尺寸为 40*10 的条形码，并隐藏下方文字。": "（4）サンプルコード：  \n- `#{[qrcode]FieldName$[20*20]$}` は、20×20固定サイズのQRコードを生成します。  \n- `#{[barcode]FieldName$[40*auto]$}` は、幅40で高さが自動調整されるバーコードを生成します。  \n- `#{[barcode]FieldName$[auto*10]$}` は、高さ10で幅が自動調整されるバーコードを生成します。  \n- `#{[barcode]FieldName$[40*10_NT]$}` は、40×10の固定サイズで下部テキストを表示しないバーコードを生成します。",
  "Mingo 搭建应用": "ミンゴアプリケーションの構築",
  "无创建应用权限": "アプリの作成権限がありません",
  "您当前所在的组织均没有创建应用的权限，请联系组织管理员。": "アプリを作成する権限がありません。管理者にお問い合わせください。",
  "网络繁忙，请稍后再试": "ネットワークが混雑しています。後ほど再度お試しください。",
  "告诉 Mingo 你想搭建的应用": "ミンゴに作成したい内容を伝えてください",
  "开启后，当月剩余执行额度为2%时，自动购买 10信用点/1万行 的单月包，从账户信用点余额中扣款。": "有効化すると、月間クォータが2％未満になった際に、システムが自動的に10クレジットのアドオンパック（10,000行分）を購入し、アカウント残高からクレジットが差し引かれます。",
  "已自动添加引用字段，以确保模板完整可用": "テンプレートが正常に機能するよう、参照フィールドが自動で追加されます",
  "编辑字段模板": "フィールドテンプレートの編集",
  "添加字段模板": "フィールドテンプレートを追加",
  "创建字段模板": "フィールドテンプレートを作成",
  "暂无模板": "利用可能なテンプレートはありません",
  "设置判断条件，然后根据判断结果true或false来返回不同的文本": "条件がTRUEかFALSEかによって、異なるテキストを返します。",
  "判断多个条件中是否有任意一个条件成立，只要有一个参数为逻辑值true，OR函数就返回true。如果所有参数都为逻辑值false，OR函数才返回false": "いずれかの条件がTRUEの場合はTRUEを返し、すべての条件がFALSEの場合のみFALSEを返します。",
  "示例：=OR($语文分数$<=60,$英语分数$<=60,$数学分数$<=60) ，结果：true": "サンプル：=OR($Chinese Score$<=60, $English Score$<=60, $Math Score$<=60)、結果：true",
  "判断多个条件是否同时成立，如果所有参数都为逻辑值true，AND函数将返回true，只要其中一个参数为逻辑值false，AND函数就返回false": "すべての条件がTRUEの場合にのみTRUEを返します。いずれかの条件がFALSEの場合はFALSEを返します。",
  "示例：=AND($语文分数$>=60,$英语分数$>=60,$数学分数$>=60) ，结果：false": "サンプル：=AND($Chinese Score$>=60, $English Score$>=60, $Math Score$>=60)、結果：false",
  "对逻辑值求反。如果逻辑值为false，NOT函数将返回true；如果逻辑值为true，NOT函数将返回false": "論理値を反転します。TRUEはFALSEに、FALSEはTRUEに変わります。",
  "示例：=NOT($分数$==60) ，结果：true": "サンプル：=NOT($score$==60)、結果：true",
  "直接返回逻辑值 false": "falseを返します",
  "示例：=FALSE() ，结果：false": "サンプル：=FALSE()  \n結果：false",
  "直接返回逻辑值true": "TRUEを返します",
  "示例：=TRUE() ，结果：true": "サンプル：=TRUE()、結果：true",
  "判断单元格是否为空，如果为空，返回true，否则返回false": "セルが空の場合はTRUEを返し、空でない場合はFALSEを返します。",
  "示例：=ISBLANK($年龄$)，结果：true": "サンプル：=ISBLANK($age$)、結果：true",
  "ENCODEURI(文本)": "ENCODEURI（テキスト）",
  "转义": "エスケープ",
  "ENCODEURICOMPONENT(文本)": "ENCODEURICOMPONENT（テキスト）",
  "示例：=ENCODEURICOMPONENT('name=明道云')，结果：'name%3D%E6%98%8E%E9%81%93%E4%BA%91'": "サンプル：=ENCODEURICOMPONENT('name=mingdao')、結果：'name%3D%E6%98%8E%E9%81%93%E4%BA%91'",
  "DECODEURICOMPONENT(文本)": "DECODEURICOMPONENT(text) をデコード",
  "示例：=DECODEURICOMPONENT('name%3D%E6%98%8E%E9%81%93%E4%BA%91')，结果：\"name=明道云\"": "サンプル：=DECODEURICOMPONENT('name%3D%E6%98%8E%E9%81%93%E4%BA%91')、結果：\"name=mingdao\"",
  "示例：=INCLUDE(\"上海市闵行区钦州北路\",'闵行')，结果：true": "サンプル：=INCLUDE(\"上海市閔行区欽州北路\", '閔行'), 結果：true",
  "在上一个节点完成后，延时到指定的日期后再继续执行流程": "前のノードが完了した後、指定した日付までフローを遅延させます。",
  "预估费用：计算中…": "見積もりコスト：計算中...",
