  "请求过于频繁，请稍后再试": "リクエストが集中しています。時間をおいて再度お試しください。",
  "自定义动作 %0": "カスタムアクション %0",
  "准备中": "準備中",
  "创建视图与自定义动作": "ビューを作成  \nカスタムアクション",
  "自定义页面准备中": "カスタムページを準備しています",
  "工作流准备中": "ワークフローを準備中です",
  "自定义动作工作流准备中": "カスタムアクションワークフローの準備",
  "创建自定义动作工作流": "カスタムアクションワークフローを作成",
  "重命名成功": "名前の変更が完了しました",
  "创建工作台": "ホーム作成",
  "推荐待搭建应用": "おすすめのアプリ構築",
  "「AI 福利点」（1福利点=1个信用点）可用于抵扣 mingo 中AI搭建和查询功能费用，组织所有用户共享；使用 AI 搭建应用时会优先消耗 AI 福利点，额度用尽后再从通用信用点扣费": "AI無料クレジット（1ギフトクレジット＝1クレジット）は、MingoのAI構築およびクエリ機能の利用料金に適用できます。全ユーザーで共有されており、一般クレジットより先に消費されます。",
  "Mingo AI 功能": "Mingo AI 機能",
  "关闭后，当AI福利点用完后，将不会继续扣除信用点，且无法使用MingoAI付费功能": "無効にすると、AI無料クレジットが消費された後は組織クレジットが使用されません。クレジットベースのMingo AI機能はご利用いただけなくなります。",
  "Mingo搭建—AI搭建应用、创建工作表、填充示例数据、优化名称和图标、填写记录": "Mingoセットアップ — AIエージェントでアプリを構築します。ワークシートの作成、サンプルデータの追加、名称やアイコンの調整、レコードの入力を行います。",
  "Mingo查询—使用Mingo查询应用数据": "Mingoクエリ — Mingoでアプリデータを検索します",
  "使用帮助问答不扣费": "ヘルプQ&Aは無料です",
  "「信用点」用于系统中Mingo AI功能、发送邮件、短信等计费服务自动扣费。为避免系统功能不可用，请确保账户信用点余额充足。": "クレジットは、ミンゴAI機能、メール、SMSなどの課金サービスに自動的に適用されます。サービスの中断を防ぐため、十分な残高を維持してください。",
  "其中「AI 福利点」为平台赠送额度（1福利点=1个信用点），仅抵扣 Mingo AI功能费用；使用时会优先消耗 AI 福利点，额度用尽后再从通用信用点扣费。": "AI無料クレジットは、プラットフォームから付与されるクレジットであり、Mingo AI機能専用です（1 AI無料クレジット＝1クレジット）。  \nAI無料クレジットは優先的に消費され、残高がなくなった後に一般クレジットが差し引かれます。",
  "完成步骤 1 后，填入CorpId、AgentId、ClientId、ClientSecret后可对接应用与同步通讯录": "Step 1の後、CorpId、AgentId、ClientId、ClientSecretを入力してアプリと連携し、連絡先を同期します。",
  "获取扣费明细失败": "請求情報の取得に失敗しました",
  "获取AI福利点记录失败": "AI無料クレジットの記録を取得できませんでした",
  "信用点消费": "クレジット",
  "扣费明细": "請求詳細",
