  "查看扣费明细": "請求詳細ビューを表示",
  "暂无AI福利点消耗记录": "AIクレジットの消費履歴はありません",
  "组织 - 账务": "オーグ - 請求",
  "AI 福利点消费": "AI無料クレジット",
  "「AI 福利点」为平台赠送额度（1福利点=1个信用点），仅抵扣 Mingo AI 功能费用；使用时会优先消耗 AI 福利点，额度用尽后再从通用信用点扣费。": "「AI無料クレジット」は、プラットフォームから付与されるクレジットで、Mingo AI機能専用です（1 AI無料クレジット＝1クレジット）。先にAI無料クレジットが消費され、残高がなくなった場合は一般クレジットが差し引かれます。",
  "每月赠送200福利点，当月1日00:00自动刷新，不累加。   -----付费版第二段，200为根据版本变量": "毎月200クレジット付与、毎月1日0:00に自動リフレッシュ、繰越不可  \n——有料プラン（レベル2）、200クレジットはプランにより異なります",
  "免费版为一次性赠送，升级到付费版后可享每月赠送额度。-----免费版第二段": "フリープランは一度限りの提供です。有料版では毎月の利用枠が含まれます。——フリープラン、レベル2",
