  "每月赠送%0福利点，当月1日00:00自动刷新，不累加。": "毎月、%0の無料ギフトクレジットを獲得できます。クレジットは毎月1日00:00に自動でリフレッシュされ、繰り越しはできません。",
  "免费版为一次性赠送，升级到付费版后可享每月赠送额度。": "フリープランには、1回限りのクレジット付与が含まれています。 有料プランには、毎月のクレジット付与が含まれています。",
