  "全组织所有应用可见，可使用": "アプリは組織全体で利用できます、",
  "允许审批人在记录详情页、邮件内快速处理审批任务。在快速处理审批时将忽略表单中的必填字段。": "承認者がレコード詳細ページやメール上で、必須項目を入力せずに迅速に承認作業を行えるようにします。",
  "操作导入升级": "アプリアップグレードのインポート",
  "应用”%0”正在导入升级，完成后会通知您": "「%0」のインポートおよびアップグレードを実行しています。完了次第、通知いたします。",
