  "如需获取合同，请拨打400-665-6655，我们将尽快为您提供。如需获取发票，请在完成支付后前往 组织管理 -> 账务中心，自助申请。": "契約に関するご相談は、400-665-6655までご連絡ください。  \n請求書に関しては、支払い完了後にオーグ管理者メニューの「請求」から申請してください。",
  "包含无法归属到具体应用的功能用量，例如 API 集成": "API連携など、特定のアプリに紐づかない利用も含まれます。",
  "每月1日00:00自动刷新为 %0 福利点，不累加": "毎月1日00:00に%0の無料クレジットが自動的にリフレッシュされます。繰り越しはできません。",
  "「信用点」用于发送邮件、短信等计费服务自动扣费。为避免系统功能不可用，请确保账户信用点余额充足。": "クレジットは、メールやSMSなどの有料サービスに使用されます。サービスの利用が途切れないよう、残高を十分に保ってください。",
