  "条%26077": "メッセージ",
  "非中国大陆地区": "中国本土以外",
  "允许将视图公开分享，获得链接的所有人都可以查看视图和视图下的全部记录": "公開ビューの共有を許可し、リンクを知っているユーザーはビューおよびすべてのレコードにアクセスできます",
  "允许将记录公开分享，获得链接的所有人都可以查看记录": "リンクによる公開共有を許可",
  "公开分享链接": "パブリック共有リンク",
  "使用业务库创建用户": "ビジネスライブラリでユーザーを作成",
  "通过解析内部成员访问或公开分享的记录链接来获取对应的记录对象，供流程中的其他节点使用。场景例如：仓库管理员在PC端使用扫描枪来扫描商品的二维码，将指向的记录链接写入文本框，由工作流解析出关联的产品，实现自动化出入库。": "リンクを解析して該当するレコードオブジェクトを抽出し、他のワークフローノードで利用できます。これにより、倉庫管理者が商品QRコードをシステムに読み取った際に、在庫管理を自動化できます。",
  "选中记录不满足条件": "選択したレコードは条件を満たしていません",
  "○ 创建「唯一索引」时，选择的索引字段在已有记录里不能存在重复值（包含回收站内的记录）；": "○ ユニークインデックスを作成する際は、フィールド値がリサイクルビン内のレコードも含めてグローバルで一意である必要があります；",
  "○ 一张工作表只能创建一个「文本索引」；": "○ 各ワークシートでは、テキストインデックスを1つのみ設定できます；",
  "每张工作表只能创建一个「文本索引」；创建「文本索引」时，不能包含「选项字段」；每个索引只能包含一个「选项字段」": "各テーブルにはテキストインデックスを1つのみ設定できます。テキストインデックスにはセレクトフィールドを含めることはできません。また、各インデックスにはセレクトフィールドを1つのみ含めることができます。",
  "20秒": "20秒",
  "示例：=ENCODEURICOMPONENT('name=系统')，结果：'name%3D%E7%B3%BB%E7%BB%9F'": "サンプル: =ENCODEURICOMPONENT('name=system')、結果: 'name%3D%E7%B3%BB%E7%BB%9F'",
  "示例：=DECODEURICOMPONENT('name%3D%E7%B3%BB%E7%BB%9F')，结果：\"name=系统\"": "サンプル：=DECODEURICOMPONENT('name%3D%E7%B3%BB%E7%BB%9F')、結果：\"name=system\"",
  "版本%26016": "バージョン",
  "升级后将立即执行发布更新，升级期间应用无法正常使用，完成后会推送结果。请确认此操作。": "アップグレード完了後、直ちにアップデートが公開されます。この間、アプリはご利用いただけません。完了次第、通知いたします。続行しますか？",
