  "免审": "承認は不要です",
  "1、沙盒是完全独立的测试环境，应用结构与数据与生产环境完全隔离。共用生产环境的组织架构、API 集成、插件。": "1、サンドボックスは完全独立したテスト環境であり、アプリ構成やデータは本番環境から完全に隔離されています。なお、組織構造、API連携、プラグインは本番環境と共有されます。",
  "2、应用开启沙盒环境后，正式环境中的结构将被锁定。在沙盒环境测试与开发，不会影响正式环境的运行，验证通过后可以发布至正式环境。": "2、サンドボックスを有効化すると、本番環境の構成がロックされます。サンドボックス内での開発・検証は本番業務に影響を与えず、検証完了後に本番環境へ反映できます。",
  "3、不同环境中运行产生的通知、计费、日志数据也完全隔离。": "3、通知、請求、およびログデータは、各環境ごとに完全に分離されています。",
