  "在文件预览和下载时叠加水印。只支持文件大小%0以内图片水印。目前支持的图片的格式为：jpeg、png、tiff、bmp、heif": "ウォーターマーク付きファイルのプレビューおよびダウンロードが可能です。ファイルサイズが%0未満の場合のみ画像ウォーターマークに対応しています。対応形式：JPEG、PNG、TIFF、BMP、HEIF",
  "列样式与工作表保持一致": "ワークシートの列スタイルを一致させる",
  "继承关联工作表设置的列样式。": "連携されたワークシートのスタイルを継承します。",
  "继承关联工作表设置的列样式。如果指定的关联视图是表格视图、则使用该视图设置的列样式。": "リンクされたワークシート、または指定された場合はそのテーブルビューの列スタイルを継承します。",
  "使用本节点前，请先确认已有蓝字发票。电子开票为异步处理，节点执行时会等待开票结果后再继续。此节点为自动开票，无需管理员审核。": "このノードを使用する前に、必ず青色伝票が発行されていることを確認してください。電子インボイスの処理は非同期で行われ、結果が返されるまで実行は待機します。本ノードは、管理者の承認なしで自動的にインボイスを発行します。",
  "添加关注者": "フォロワーを追加",
  "将指定用户添加为记录关注者，关注者将在记录更新或新增讨论时收到通知": "選択したユーザーをこのレコードのフォロワーとして追加します。レコードが更新された場合や新しいコメントが投稿された場合に通知されます。",
  "移除关注者": "フォロワーを削除",
  "将指定用户从记录关注者中移除，移除后将不再接收该记录的通知": "選択したユーザーをフォロワーから削除します。該当レコードの通知が届かなくなります。",
  "覆盖关注者": "フォロワーを上書き",
  "使用指定用户替换当前关注者列表，原有关注者将被移除": "現在のレコードのフォロワーを、選択したユーザーに置き換えます。既存のフォロワーはすべて削除されます。",
  "通过该节点可更新记录的关注用户，包括添加、移除或覆盖关注者。关注者将在新增讨论时收到系统通知。": "レコードのフォロワーを更新します（追加・削除・上書き）。フォロワーには新しいディスカッションのシステム通知が届きます。",
  "更新方式": "更新メソッド",
  "关注者": "フォロワー",
  "关注者不能为空": "フォロワーを空欄にすることはできません",
  "启用安全验证": "セキュリティ認証を有効化",
  "开启后，执行该操作时需完成身份校验，验证方式以操作人个人账户的安全设置为准。": "有効化すると、このアクションはユーザーのセキュリティ設定に基づいた本人確認が必要になります。",
  "获取第三方企业身份 ID": "サードパーティ企業ID連携IDを取得",
  "同时获取第三方企业身份 ID": "サードパーティ企業のIDを含める",
  "同时获取当前组织组织已集成的第三方用户 ID（企业微信/钉钉/飞书/Lark/Miacrosoft Entra）；如果您的使用场景无需第三方用户 ID，推荐不勾选以提升您的查询效率": "ご利用中の組織に連携されている外部ユーザーID（WeCom、DingTalk、Lark、Microsoft Entra）を取得します。不要な場合は、このオプションの選択を解除することで、クエリのパフォーマンスを向上させることができます。",
  "允许审批/填写人添加抄送人": "CC受信者の追加を許可",
  "开启后，审批人或填写人在处理当前节点时，可手动添加抄送人；被添加的抄送人可查看当前记录的相关内容。": "有効にすると、承認者または担当者がユーザーを手動でCCでき、該当レコードの詳細を閲覧できるようになります。",
  "校验登录身份": "ログイン認証",
  "开启后，点击邮件中的审批按钮时，需先登录并校验当前账号是否为该审批的可操作人，校验通过后才可完成审批操作": "有効化すると、メール承認ボタンをクリックした際、承認完了前にログインおよび認証確認が必要です。",
  "更新记录关注者": "レコードメンバーを更新",
  "添加或移除记录关注用户，关注者可接收记录相关通知": "レコードのフォロワーを追加または削除して、レコードの通知を受け取れるようにします。",
  "货物运输服务明细开票": "貨物運送サービスの請求書を発行",
  "仅限货物运输服务行业的明细开票": "貨物輸送サービス専用の請求書を発行します",
  "发票冲红": "クレジットノートを発行",
  "针对通过开票节点开具的蓝票进行冲红操作。": "このノードで作成された青色の請求書を取り消すため、赤伝票を発行します。",
  "分区（%0）": "パーティション（%0）",
  "首次加入排队时间": "初回キュー時間",
  "工作流配置为“分区严格串行”时，运行中的工作流需要等待前序的流程执行完毕": "厳格なパーティションのシリアルモードでは、実行中のワークフローは前のワークフローの完了を待つ必要があります。",
  "分区严格串行模式下，至少选择一个字段": "シリアル分割モードでは、少なくとも1つのフィールドを選択してください。",
  "分区严格串行": "パーティションごとの厳密なシリアル実行",
  "相同字段值的数据属于同一分区，分区内按顺序严格串行，分区之间并行": "フィールド値でグループ分けされたパーティションごとに処理されます。各パーティション内では順次実行され、パーティション間では並行して実行されます。",
  "已选择 %0 条数据": "%0件のデータが選択されています",
