  "可恢复%0天内删除的应用，超过%0天以上的应用会被物理删除，应用和数据不可恢复": "削除されたアプリケーションは%0日以内であれば復元できます。%0日を過ぎると、アプリおよびデータは完全に削除され、復元できなくなります。",
