  "开启沙盒后，正式环境中的应用结构将被锁定，所有调整均需通过发布进行更新，您可按需同步部分生产数据用于调试。关联应用也需开启沙盒，否则会导致引用失效。": "サンドボックスを有効化すると、本番アプリの構造はロックされ、変更を反映させるには公開が必要です。テスト用に選択した本番データをデータ同期できます。関連するアプリも参照の断絶を防ぐため、サンドボックスを有効化する必要があります。",
