  "支持登录密码、短信验证码、邮件验证码、身份验证器 4 种验证方式。短信、邮件验证码需先绑定手机号或邮箱；身份验证器需先开启两步认证并完成配置。": "以下の認証方法に対応しています：ログインパスワード、SMSコード、メールコード、認証アプリです。  \nSMSおよびメールは事前の連携が必要です。認証アプリは2段階認証の設定と構成が必要です。",
