  "加载更多...": "さらに表示",
  "自定义签名到达率受运营商风控等因素影响，若实际到达率不佳，建议您可以尝试切换到平台默认提供的签名。针对港澳台及国际地区的短信发送，无需额外配置短信签名。": "カスタム署名の配信率は、キャリアの制限により影響を受ける場合があります。配信率が低い場合は、プラットフォームのデフォルト署名のご利用をご検討ください。香港、マカオ、台湾、または海外へのSMS送信には追加設定は不要です。",
