  "更换微信服务号会导致已绑定的 openid 失效，可能出现模板消息发送失败、外部门户无法登录、公开表单微信信息获取异常。非必要请勿更换；如需更换，请提前做好数据与账号迁移。": "WeChatサービスアカウントを切り替えると、既存のopenidが無効となり、テンプレートメッセージの配信失敗、外部ポータルへのログイン不可、または公開フォームからのWeChat情報取得時のエラーが発生する可能性があります。必要がない限り、アカウントの切り替えは行わないでください。やむを得ず切り替える場合は、事前にデータおよびアカウントの移行を実施してください。",
