  "允许一小时内免验证": "1時間検証をスキップ",
  "每次操作均需验证": "各アクションを検証",
  "允许一小时内免验证 (默认)": "1時間検証をスキップ（デフォルト）",
  "对审批、自定义动作等敏感操作进行密码验证时，允许用户在一次验证通过后的 1 小时内免于重复验证；管理员可选择禁用该策略，禁用后将不再提供免验证选项，每次操作时均需进行密码验证，适用于安全等级要求高的场景。": "承認やカスタムアクションなどの機密性の高い操作で認証に成功した後、1時間以内であればパスワード認証を省略できるようにします。管理者はこのポリシーを無効化することができ、無効化後はパスワード認証の省略ができなくなり、すべての操作で毎回パスワード認証が必要となります。高度なセキュリティが求められるシナリオでの利用を推奨します。",
  "用户 - 群组": "ユーザー - グループ",
  "当前用户数已经达到限额": "ユーザー上限に達しました",
  "请去购买": "購入ページへ",
  "，请": "，",
  "用户 - 外部门户": "ユーザー - 外部ポータル",
