  "用户 - 角色": "ユーザー - ロール",
  "对手机号字段进行短信验证。发送至中国大陆区的短信费用将自动从组织信用点扣除，信用点不足时无法获取验证码。": "SMSで携帯電話番号フィールドの認証を行います。中国本土へのSMS送信には、組織のクレジットが消費されます。クレジットが不足している場合、認証コードは受信できません。",
  "发送港澳台/国际短信需确保已配置服务商，否则无法送达。 短信签名默认跟随平台签名，发送港澳台/国际短信无需配置短信签名。": "HK・MO・TWまたは国際番号へのメッセージ送信前に、SMSプロバイダーの設定を行ってください。SMSの署名はデフォルトでプラットフォーム署名が適用されます。国際地域では追加の署名は不要です。",
