  "快麦云配置": "Kuaimai Config",
  "在快麦云开放平台中创建打印模板并配置字段。填写打印设备序列号和模板 ID，用于建立打印通道。": "KuaiMai Open Platformで印刷テンプレートを作成し、フィールドを設定します。プリンターのシリアル番号とテンプレートIDを入力して、印刷チャネルを構成します。",
