  "请在快麦后台「设备管理」中获取设备序列号，并填写至此。": "KuaiMaiコンソールのデバイス管理からデバイスのシリアル番号を取得し、こちらに入力してください。",
  "打印模版 ID": "テンプレートID",
  "请在快麦后台「标签编辑」页面复制模板 ID 填写至此。": "KuaiMaiコンソールのタグ編集ページからテンプレートIDをコピーし、こちらに入力してください。",
