  "则显示样式": "表示スタイル",
  "部分字段仅支持对字段名称生效（如定位等）。选择多个字段时，不支持字段值样式的字段，其字段值样式不生效。": "「ロケーション」など一部のフィールドは、名前のスタイリングのみ対応しています。複数のフィールドを選択した場合、未対応のフィールドには値のスタイリングは適用されません。",
