  "集成失败": "連携に失敗しました",
  "开放平台提供的 appSecret 与 appSecret，用于完成明道云与第三方云打印服务的安全对接。配置完成后，明道云将通过云端接口向快麦云发送打印指令，由快麦云负责将数据转发至已绑定的打印设备，实现小票、标签等场景的远程打印能力": "Open Platformで提供されるappSecretを使用することで、Mingdao Cloudとサードパーティのクラウド印刷サービスを安全に連携できます。設定後、Mingdao CloudはAPI経由でKuaiMai Cloudに印刷コマンドを送信し、KuaiMai Cloudが接続されたプリンターにデータを転送します。これにより、レシートやラベルなどのリモート印刷が可能になります。",
  "appID": "アプリID",
