  "短信签名是附加在短信内容前面的标识，仅适用于中国大陆区，默认跟随平台签名；发送港澳台/国际短信无需配置短信签名": "中国本土で送信されるSMSには、デフォルトでSMS署名が先頭に付加されます。プラットフォーム署名が標準で適用されます。香港・マカオ・台湾および海外地域では署名は不要です。",
  "已接入国际短信": "国際SMS対応",
