  "Twilio集成": "Twilio連携",
  "填写Twilio账户的 API Key SID 与 API Key Secret，用于工作流短信节点、公开表单验证及外部门户（验证/邀请/审核）等服务。如果是Twilio免费账户，则只能向Twilio平台验证过的手机号发送消息。": "TwilioのAPI Key SIDとAPI Key Secretを入力すると、ワークフローのSMSノード、公開フォームの認証、外部ポータルサービス（認証・招待・レビュー）が利用可能になります。  \nTwilioの無料アカウントでは、Twilioプラットフォームで認証済みの電話番号にのみメッセージを送信できます。",
