  "平台统一提供的集成应用，组织可配置使用范围，成员授权后以个人权限访问数据。": "Translate Platformは、統合されたアプリケーションを一元的に提供します。  \n組織は利用範囲を設定でき、メンバーは認証後に自身の権限に基づいてデータにアクセスできます。",
  "立即开通": "今すぐ有効化",
  "1、 公共应用由平台统一提供并维护，适用于通用的第三方集成场景": "パブリックアプリはプラットフォームによって提供・管理されており、一般的なサードパーティ連携シナリオに適しています。",
  "2、 管理员可配置公共应用是否在本组织启用，并设置可授权的成员及可访问的数据范围": "管理者は、組織向けにパブリックアプリを有効化し、承認済みメンバーおよびアクセス可能なデータ範囲を設定できます。",
