  "发送港澳台或国际短信需先配置服务商，否则将无法送达。请前往组织后台完成配置。": "香港・マカオ・台湾または海外へのSMS送信前に、管理コンソールで国際サービスプロバイダーを設定してください。",
  "标点、空格及字母均计为 1 个字。发送至中国大陆地区的短信超 70 字（含签名）按 67 字/条计费。": "句読点、スペース、文字はそれぞれ1文字としてカウントされます。中国本土へのSMS送信の場合、署名を含めて70文字を超えるメッセージは67文字ごとに1通として課金されます。",
  "注意：若发送对象为外部用户，请选择与外部门户一致的微信服务号，否则会发送失败。": "注: 送信先が外部ユーザーの場合は、外部ポータルと同じWeChatサービスアカウントを選択してください。そうでない場合、メッセージは送信されません。",
