  "分块后，向量化相关数据": "チャンク化後の関連データをベクトル化",
  "将应用数据转化为 AI 可理解的知识。通过向量化技术，实现基于自然语言的语义检索": "アプリデータをAIが理解可能な知識に変換します。ベクトル化技術により、自然言語でのセマンティック検索を実現します。",
