  "取消初始化": "アンイニシャライズ",
  "编辑信息": "情報の編集",
  "创建并维护应用的向量知识库。你可根据业务变化随时调整配置或停用索引": "アプリのベクトルナレッジベースを作成・管理できます。ビジネスのニーズに応じて、設定の調整やインデックスの無効化をいつでも行えます。",
  "重新初始化": "再初期化",
