  "删除知识库 “%0”": "ナレッジベース「%0」を削除",
  "删除后，所有向量化内容将被永久清空，相关工作流节点将无法检索此知识库。": "一度削除すると、すべてのベクトル化されたコンテンツが完全に消去され、関連するワークフローノードから本ナレッジベースへのアクセスができなくなります。",
  "我确认删除知识库及所有向量化内容": "ナレッジベースおよび全ベクトル化コンテンツの削除を確認してください",
  "重新初始化知识库": "ナレッジベースを再初期化",
  "确认后，将先删除所有内容，再重新初始化。在此期间无法检索该知识库。": "確認後、すべてのコンテンツが削除され、初期化されます。処理中はこのナレッジベースをご利用いただけません。",
  "我确认重新初始化知识库": "ナレッジベースの初期化を確認",
  "统计设置": "分析設定",
  "设置需要统计的字段及其统计方式": "フィールドおよび集計方法を設定",
  "可在表格中查看更多字段数据，最大批量选中的记录数量为100条。": "テーブルでさらに多くのフィールドデータを表示できます。一度に最大100件のレコードを選択できます。",
  "列表仅显示标题字段，支持批量选中更多记录。": "リストにはタイトル項目のみ表示されます。複数のレコードをまとめて選択できます。",
