  "流程中止时更新": "フロー終了の更新",
  "流程中止后，更新数据对象的字段值": "ワークフロー終了後にデータオブジェクトのフィールドを更新",
  "审批流程中允许查看他人填写字段": "他のユーザーが入力したフィールドの閲覧を許可",
  "新增失败时继续执行": "作成失敗時に継続",
  "审批和填写节点中查看他人填写内容": "承認ノードおよびフォームノードで他のユーザーの入力内容を閲覧できます",
  "未勾选时，如果新增失败（如工作表中配置了唯一索引）则中止流程。勾选后，则仍继续执行，此时本节点数据对象为空，后续节点在使用本节点时将跳过。": "未選択の場合、作成に失敗すると（ワークシートのユニークインデックスなどが原因）、ワークフローは停止します。選択した場合、ワークフローは継続され、このノードのデータオブジェクトは空となり、後続のノードは本ノードをスキップします。",
  "最多重复": "最大繰り返し回数",
  "检索类型": "検索タイプ",
  "检索类召回数量(TOP K)": "検索リコール数（TOP K）",
  "融合排序参数": "マージソートパラメーター",
  "用于融合“向量+全文”的排序。数值越大排序波动越小，越小越强调最靠前结果；建议默认 60。": "ベクトル検索結果と全文検索結果を組み合わせる際のランキング制御値です。値を大きくするとランキングのばらつきが抑えられ、小さくすると上位結果が優先されます。デフォルトは60です。",
  "相关度阈值": "関連性しきい値",
  "低于该值的结果将被过滤；调高更严格（结果更少更准），调低更宽松（结果更多）。": "この値より低い結果は除外されます。値を上げると、より厳密かつ正確な結果が得られます。値を下げると、より幅広い結果が表示されます。",
  "其他应用下的知识库": "他のアプリのナレッジベース",
  "检索内容": "検索コンテンツ",
  "混合检索：同时使用语义理解和关键词匹配，兼顾精准度和全面性，效果最均衡。": "ハイブリッド検索：セマンティック検索とキーワードマッチングを組み合わせ、精度と網羅性のバランスを実現。",
  "AI 智能选择：由系统智能判断最合适的检索方式，无需手动选择，适合大多数场景。": "AIセレクト：最適な検索方法を自動で判定します。手動設定は不要で、ほとんどのシーンに対応しています。",
  "语义检索：根据问题的含义去理解和匹配，即使用词不同也能找到相关内容，适合自然语言提问。": "セマンティック検索：質問の意味に基づいて理解・マッチングを行うため、表現が異なっていても関連する結果を表示します。自然言語での検索に or クエリに最適です。",
  "关键词检索：根据关键词进行匹配查找，适合搜索包含特定词汇、名称或编号的内容。": "キーワード検索：特定の単語、名称、IDでコンテンツを検索します。",
