  "指定位置": "ロケーションを設定",
  "固定位置": "ピン留め",
  "默认视图显示": "デフォルトビュー表示",
  "当前位置需要站点使用 HTTPS 才能生效；否则将使用默认城市。": "このロケーションを有効にするには、サイトがHTTPSである必要があります。HTTPSでない場合は、デフォルトの都市が使用されます。",
  "设置位置": "ロケーションを設定",
  "成员字段用于识别重复记录时，仅支持“人员ID”匹配，请修改匹配方式": "メンバー項目で重複レコードの照合に使用できるのは「User ID」のみです。照合方法を変更してください。",
  "支持的字段类型：文本、电话、邮箱、证件、自动编号、记录ID、成员(单选)。选择多个字段时需同时匹配(\"且\"关系)，最多支持5个字段": "対応フィールドタイプ：テキスト、電話番号、メールアドレス、ID、自動採番、レコードID、メンバー（単一選択）\n\n複数のフィールドを選択する場合、すべての条件を満たす必要があります（AND条件）。\n\n最大5つのフィールドまで対応しています。",
  "新增%0行记录，更新%1行记录，其中%2个附件导入失败": "%0 件のレコードを追加し、%1 件のレコードを更新しました。%2 件の添付ファイルはインポートに失敗しました。",
  "非组织超级管理员无法修改组织超级管理员姓名/手机号/邮箱": "組織のスーパー管理者の氏名、電話番号、またはメールアドレスの編集は、組織のスーパー管理者のみが行えます。",
