  "正在为数据库\"向量数据库名称\"添加新的工作表，请为选中的工作表添加需要语义分析的文本类型字段或记录讨论": "データベース「Vector Database Name」に新しいワークシートを追加します。選択したワークシートに、セマンティック分析やディスカッション記録用のテキストフィールドを追加してください。",
  "对已向量化的数据同时生效": "ベクトル化データに適用",
  "知识范围或解析方式有调整。确认保存后将对已向量化的数据重新向量化。重新向量化需要一定时间，此期间该知识源暂无法被检索。": "ナレッジ範囲または解析方法が更新されました。保存後、既存のベクトル化データはすべて再ベクトル化されます。この処理中、本ナレッジソースは一時的に検索できなくなります。",
  "知识范围或解析方式有调整，确认保存后将对新变更的数据生效，历史数据不受影响。": "スコープや解析方法の変更は、保存後に追加される新しいデータにのみ適用されます。既存のデータには影響しません。",
  "重新向量化工作表": "ワークシートの再ベクトル化",
  "确认后，将先删除所有内容，再重新向量化。在此期间无法检索此工作表。": "確認後、すべてのコンテンツが削除され、再ベクトル化されます。この処理中は、ワークシートのクエリは実行できません。",
  "我确认重新向量化工作表": "ワークシートの再ベクトル化を確認",
