  "开始优化": "今すぐ最適化",
  "我根据当前应用信息，智能优化名称、图标。如果您对优化内容有具体要求也可以告诉我。": "現在のアプリ情報をもとに、名前とアイコンを最適化します。ご要望がありましたらお知らせください。",
  "启用后，超过保留周期的执行历史将自动删除且不可找回（不包含审批流程执行历史），请谨慎使用。": "有効化すると、保持期間を超えた実行履歴は自動的に削除され、復元できません（承認プロセス履歴を除きます）。ご注意の上、操作してください。",
  "勾选后，超过保留周期的执行历史将自动删除且不可找回，请谨慎使用。": "有効化すると、保持期間を超えた実行履歴は自動的に削除され、復元できません。ご注意のうえご利用ください。",
