  "知识库当前模型Qwen Embedding-v3-0.6b已失效。确认后，系统将先删除所有内容，并使用平台默认嵌入模型Qwen Embedding-v3-8b重新初始化。": "現在のナレッジベースモデル「Qwen Embedding-v3-0.6b」は無効となりました。確認後、すべての内容が削除され、システムはデフォルトの埋め込みモデル「Qwen Embedding-v3-8b」で再初期化されます。",
