  "选择主表": "メインテーブルを選択",
  "请选择打印数据的主表。系统将以该表作为主要数据来源，其余表将自动按动态表格（关联类型）处理。": "印刷用の主要なデータソースとしてメインテーブルを選択します。関連テーブルはシステムが自動的に動的管理します。",
  "开放平台提供的 appId 与 appSecret，用于完成与第三方云打印服务的安全对接。配置完成后，系统将通过云端接口向快麦云发送打印指令，由快麦云负责将数据转发至已绑定的打印设备，实现小票、标签等场景的远程打印。": "オープンプラットフォームのAppIdおよびAppSecretを設定し、サードパーティのクラウドプリントサービスと安全に連携します。設定完了後、システムはクラウドAPIを通じてKuaMai Cloudに印刷指示を送信し、KuaMai Cloudが連携済みプリンターに伝達することで、レシートやラベルなどをリモート印刷できます。",
  "appId": "アプリID",
  "确认退出？": "サインアウトしますか？",
  "当前内容校验未通过，确认是否退出。": "検証に失敗しました。本当に終了してもよろしいですか？",
