  "只在admin数据库中可用，赋予用户所有分片和复制集相关函数的管理权限;": "管理データベースでのみ利用可能です。すべてのシャーディングおよびレプリカセット機能の管理権限を付与します。",
  "只在admin数据库中可用，赋予用户所有数据库的读权限;": "管理データベースでのみ利用可能です。すべてのデータベースへの読み取り権限を付与します。",
  "只在admin数据库中可用，赋予用户所有数据库的userAdmin权限;": "管理データベースでのみ利用可能です。すべてのデータベースに対してuserAdmin権限を付与します。",
  "只在admin数据库中可用，赋予用户所有数据库的dbAdmin权限;": "管理データベースでのみ利用可能です。すべてのデータベースに対してdbAdmin権限を付与します。",
