  "在工作流AI Agent、对话机器人中使用 “知识库检索” 工具": "AIエージェントのワークフローおよびチャットボットでナレッジベースリトリーバルツールを利用する",
  "将应用数据转化为 AI 可理解的内容，让您可以通过自然语言进行检索。": "アプリデータをAIが認識可能なコンテンツに変換し、自然言語検索に対応します",
