  "创建并管理应用下的向量知识库。您可根据需要随时调整知识库配置。": "アプリ向けのベクトル型ナレッジベースを作成・管理できます。設定により、いつでも更新が可能です。",
  "删除后，知识库内容会被清空，相关工作流节点将无法检索此知识库": "削除後、ナレッジベースの内容はすべて消去され、関連するワークフローノードにはアクセスできなくなります。",
  "注：并不会删除原始工作表": "注：元のワークシートは削除されません。",
