  "配置字段（2/3）": "フィールドの設定（2/3）",
  "设置筛选条件，仅当数据符合条件时可进入知识库。支持使用选项、等级、检查项字段。": "フィルターを設定し、オプション・評価・チェックリストなどの条件に基づいて、対象データのみをナレッジベースに追加できます。",
  "点击创建后，系统将先计算分块数量和预计 Token 消耗，确认后开始向量化": "「作成」をクリックすると、チャンク数とトークン消費量が推定されます。内容を確認後、ベクトル化を開始してください。",
  "为选中的工作表添加需要检索的文本类型字段或记录讨论": "選択したワークシートに検索対象のフィールドまたはレコードを追加します",
