  "向量化入库完成可正常使用，入库过程中，无法修改知识库范围": "ベクトル化後はナレッジベースを通常通り利用できます。インポート時に範囲が確定します。",
  "正在为数据库 “%0” 添加新的工作表，请为选中的工作表添加需要检索的文本类型字段或记录讨论": "データベース「%0」に新しいワークシートを追加しています。選択したワークシートにテキストフィールドまたはノートを追加してください。",
  "知识范围有调整。确认保存后将对已分块数据重新计算分块。": "ナレッジ範囲が更新されました。保存後、システムは既存のチャンクデータを再計算します。",
  "重新向量化入库 %0": "再ベクトル化して %0 を取り込む",
  "知识库当前模型 %0 已失效。确认后，系统将先删除所有内容，并使用平台默认嵌入模型 %1 重新向量化入库。": "現在のモデル「%0」は無効です。内容をクリアし、プラットフォームのデフォルトモデル「%1」で再ベクトル化します。よろしいですか？",
