  "保存系统打印配置模板，或上传 Word、Excel 模板自定义记录打印样式，同时新增云打印功能。": "システムの印刷テンプレートを保存したり、WordやExcelのテンプレートをアップロードして印刷レイアウトをカスタマイズできます。クラウド印刷にも対応しています。",
  "图片正在上传，请稍后": "アップロード中です。しばらくお待ちください。",
  "此功能需要在钉钉中开启添加待办任务接口权限。": "DingTalkで「To-Doタスク追加API」の権限を有効にします。",
  "选择向量化内容：支持标题、讨论、附件及文本/富文本字段。每条记录分块最高容纳 3500 字，包含字段内容及附件名。": "ベクトル化されたコンテンツを選択：タイトル、ディスカッション、添付ファイル名、テキスト／リッチテキストフィールドをサポートします。各レコードは、フィールド内容および添付ファイル名を含め、1ブロックあたり最大3,500文字までとなります。",
  "知识库用量超限，请联系组织管理员增购额度": "ナレッジベースの上限に達しました。アップグレードについては管理者にお問い合わせください。",
  "从%0通讯录同步到该系统。": "%0件の連絡先をこのシステムに同期します。",
  "该配置对数据处理及知识库检索工具生效。取消勾选后，工具执行时将忽略用户数据权限，Agent可访问并返回超出用户权限范围的数据，请谨慎操作。": "有効にすると、この設定はデータ処理およびナレッジ検索ツールに適用されます。無効にした場合、ツールがユーザーデータの権限を無視し、許可範囲を超えたデータを返す可能性があります。",
  "未添加字段": "フィールドが追加されていません",
  "组织知识库用量已超限。新增数据将暂停向量化入库，但不影响已有内容的检索。如需恢复同步，请联系管理员增购额度": "ナレッジベースの上限に達しました。新しいデータはインデックス化されませんが、既存のコンテンツは検索できます。クォータの増加については管理者にお問い合わせください。",
  "【当前用户正在使用语音输入，文本内容与选项内容无需完全匹配，可以进行模糊匹配】": "【音声入力（あいまい検索対応）】",
