  "扩充向量分块数": "ベクターチャンクを展開",
  "10000个起购": "最小注文数：10,000",
  "100元 / 1W个*剩余月份": "¥100 ÷ 10,000 × 残り月数",
  "选择向量化内容：支持标题、附件及文本/富文本字段、讨论（含附件）。每条记录分块最高容纳 3500 字，包含字段内容及附件名。": "ベクトル化対象のコンテンツを選択できます。タイトル、添付ファイル、テキスト／リッチテキストフィールド、ディスカッション（添付ファイル付き）に対応しています。各レコードのチャンクには、フィールドの内容や添付ファイル名を含めて最大3,500文字まで対応します。",
  "组织授权到期，知识库相关功能不可使用": "認証の有効期限が切れました。ナレッジベースは無効化されています。",
  "该配置对数据处理及知识库检索工具生效。取消勾选后，工具执行时将忽略用户数据权限，Agent可访问并返回所有满足配置的数据，请谨慎操作。": "有効にすると、ツールはユーザーデータの権限に基づいてナレッジベースデータを処理・取得します。無効にした場合は権限を無視し、すべての設定済みデータを返しますので、ご注意ください。",
  "使用文本类型字段必须包含手机区号，否则无法发送。": "テキストフィールドには、送信する際に国番号（例：+852）を含めて入力してください。",
  "前往完成向量化": "ベクトル化に進む",
  "创建并管理应用下的向量知识库": "アプリ内でベクトル型ナレッジベースを作成・管理できます",
  "组织授权到期，知识库暂不可用。知识库内数据将保留30天，到期后自动清空": "組織のライセンスが失効しました。ナレッジベースは一時的にご利用いただけません。データは自動削除まで30日間保持されます。",
  "内容类型": "コンテンツタイプ",
  "查看具体规则": "ルールの詳細を表示",
