  "的以下权限，您可以随时撤销": "（と同様），これらはいつでも取り消し可能です。",
  "切换旧版": "旧バージョンに切り替え",
  "本次更新优化了打印模板的数据获取方式。": "今回のアップデートで印刷テンプレートのデータ取得方法を最適化しました。",
  "如遇异常，可切换到旧版继续使用。": "問題が発生した場合は、前のバージョンに切り替えてください。",
  "启用后，该集成将可以正常访问数据，请确认操作。": "有効化すると、この連携はデータへアクセスできるようになります。ご確認ください。",
  "停用后，该集成将无法继续访问任何数据，请确认操作。": "この連携を無効化すると、すべてのデータへのアクセスが失われます。よろしいですか？",
  "10000块起购": "最低購入金額：¥10,000",
  "100元 / 1W块*剩余月份": "¥100 / 10,000チャンク × 残り月数",
  "允许外部用户修改账号信息": "外部ユーザーによるアカウント情報の編集を許可",
  "生成链接后复制进”PC端首页地址“即可使用": "生成されたリンクを「PCホームページURL」にコピーしてご利用ください。",
  "1. 前往钉钉开发者平台 — 定位到“应用开发”": "1. DingTalk開発者プラットフォーム＞アプリ開発 に移動します",
  "前往钉钉开发者平台 — 定位到“应用开发”": "DingTalk開発者プラットフォームにアクセスし、アプリ開発へ移動してください。",
  "选择“应用开发”下的“企业内部应用”": "「アプリ開発」から「エンタープライズ内製アプリ」を選択してください",
  "2. 点击创建应用，完善应用信息": "2.「アプリを作成」をクリックし、アプリの詳細を入力します。",
  "3. 完善接口信息": "3. API情報の詳細",
  "定位到“网页应用”的 网页应用配置信息，讲以下链接填入对应输入框内": "Webアプリの設定で、次のリンクを入力してください。",
  "切换至“凭证与基础信息”，将AgentId、ClientId、ClientScret分别填入明道云的“组织管理 - 企业身份 - 钉钉 - 对接信息录入”对应输入框内": "「認証情報・基本情報」に移動し、「組織管理 > 組織連携 > DingTalk > 連携情報」内でAgentId、ClientId、ClientSecretを入力してください。",
