  "确认后将清空数据并重新分块（期间不可检索），分块完成后需您再次确认以开始向量化。": "すべてのデータをクリアして再チャンク化します。データは一時的に利用できなくなります。再チャンク化完了後、ベクトル化を続行するには再度確認が必要です。",
