  "100 元/1万块/年（版本剩余时间）": "¥100／10,000チャンク／年（バージョン有効期間に基づく）",
  "选择向量化内容：支持标题、文本、文本组合、富文本、级联/关联（单条）、附件字段，以及讨论（含附件）。每条记录为一个分块，包含字段名和字段值，最高容纳 3500 字；附件、记录讨论按规则单独分块。": "ベクトル化するコンテンツを選択：タイトル、テキスト、リッチテキスト、リレーション、添付ファイル、添付ファイル付きディスカッション  \n各レコードは1チャンク（最大3,500文字、フィールド名と値を含む）として処理されます。  \n添付ファイルおよびディスカッションは個別にチャンク化されます。",
  "开启后，对 %0 格式的附件使用视觉模型解析，提升复杂文档的结构还原准确率。": "有効化すると、%0形式の添付ファイルをビジュアルモデルで解析し、複雑なドキュメント構造の再現精度が向上します。",
  "\"打开Outlook，在工具>账户设置>Internet日历中新建，并粘贴\n刚才获得的ICAL格式日历地址\"": "Outlookを開き、ツール > アカウント設定 > インターネットカレンダーに移動します。新しいカレンダーを追加し、ICALアドレスを貼り付けてください。",
