  "开启后，支付订单及工作流开票的发票备注中将自动附加销方相关信息；需在百望云-基础-配置管理的销方信息页面完善销方信息。": "有効化すると、支払伝票およびワークフロー請求書の備考欄に販売者情報が自動的に追加されます。販売者情報の更新は、Baiwang Cloud ＞ 基本 ＞ 設定管理 ＞ 販売者情報から行ってください。",
  "只勾选微信登录时首次扫码后需要输入手机号与微信绑定，后续可单独微信扫码快速登录。": "WeChatログインを有効にすると、初回のスキャン時に電話番号の連携が必要です。以降は、WeChatのスキャンで即座にログインできます。",
