  "限制成员使用个人身份权限（OAuth 授权、个人访问凭证）直接调用 API，降低数据外泄风险。": "メンバーによる個人認証情報（OAuthトークンや個人アクセストークン）を使用した直接的なAPIコールを制限し、データ漏洩リスクを最小化します。",
