  "短信收费标准：短信%0/条，自动从企业账户中心扣除。70字计一条短信，超过70字以67字每条计费。每个标点、空格、英文字母都算一个字。短信实际发送可能有10-20分钟的延时。": "SMS料金：1通あたり%0がエンタープライズアカウントから自動で差し引かれます。1通のSMSには最大70文字まで含めることができ、これを超える場合は追加のSMSごとに67文字ずつ利用されます。句読点、スペース、英字もそれぞれ1文字としてカウントされます。配信には10〜20分程度の遅延が発生する場合があります。",
