  "我可以为您的工作表添加一些示例数据，方便你进行数据测试。如果您对添加的数据有具体要求也可以告诉我。": "テスト用にワークシートへサンプルデータを追加できます。ご要望がありましたらお知らせください。",
  "验证码短信%0每条，自动从企业账户扣除，信用点不足时无法获取验证码。": "認証コードの送信には、1通あたり%0の費用がかかります。クレジット残高が不足している場合、アクセスが制限されます。料金はビジネスアカウントから自動的に差し引かれます。",
