  "2、电子发票由知名数电开票合作服务商": "2. 電子請求書は、信頼できるデジタル請求パートナーによって発行されます",
  "1、完成组织的企业认证或已有支付商户号即可创建开票税号。每个开票税号开通后，享有 7 天免费试用": "1. ビジネス認証の完了または決済事業者アカウントの連携後、Tax IDを作成できます。各Tax IDには7日間の無料トライアルが付与されます。",
