  "提供。开票资料需与营业执照信息 保持一致，且真实有效": "事業許可証と一致する正確な請求先情報をご入力ください。",
  "发件人": "送信者",
  "3、已有百望账号？请联系组织管理员或平台客服人员，协助完成账号绑定": "3. すでにBaiwangアカウントをお持ちの場合は、管理者またはカスタマーサポートまで連携方法についてお問い合わせください。",
  "请您先在百望完成企业信息与登录验证等配置，否则无法开票。具体操作步骤请查看": "まず、Baiwangで会社情報の入力およびログイン認証設定を完了してください。これらが未設定の場合、請求書の発行はできません。詳細な手順については、こちらをご参照ください。",
  "1、导入的“商品管理表”将作为开票时选择的商品类目/税收分类编码的数据来源。": "1、インポートされた「Product Management Table」は、請求書作成時に商品カテゴリーや税コードの選択に使用されます。",
  "开启并确认开票登录验证（验证码/人脸认证）以保障自动开票": "自動請求書発行を確実に行うため、請求ログイン（キャプチャ認証／顔認証）を有効化し、認証を確認してください",
  "2、电子税局的商品管理表有更新时，请重新导入以同步最新税率与编码。": "2. eTaxのプロダクト管理テーブルが更新された場合は、最新の税率およびコードを同期するため、再インポートを行ってください。",
