  "企业税号（统一社会信用代码）": "法人の納税番号（統一社会信用コード）",
  "开启后，在二级域名下使用飞书扫一扫，直接登录": "有効化すると、サブドメインでLarkを使ってスキャンすることで、直接ログインできます。",
  "用于接收百望账号开通等消息通知，已有百望账号时不会发送账号信息": "Baiwangアカウントの有効化通知の受信に使用されます。既にアカウントが存在する場合は、通知は送信されません。",
  "开通7天试用": "7日間の無料トライアルを開始",
  "流程待办同步至Lark审批中心": "To-DoタスクをLark承認センターへ同期",
  "为当前开票税号开启 7 天免费试用，期间可正常开票；到期自动停用，购买后可继续使用。每个税号仅一次试用。": "現在の税務識別番号で7日間の無料トライアルを開始できます。トライアル期間中は通常通り請求書を発行可能です。トライアルは購入による延長がない限り、自動的に終了します。各税務識別番号につき、無料トライアルは1回限りご利用いただけます。",
