  "每个选项单列一行。若选项与选项列表重复，保存时将忽略重复选项；若选项与回收站内选项重复，保存时将自动恢复回收站的选项": "各オプションを1行ずつ入力してください。保存時に、リスト内の重複したオプションは無視されます。リサイクルビン内の重複オプションは自動的に復元されます。",
