  "（账号与初始密码已发送至": "(アカウント情報と初期パスワードを送信しました",
  "助力 AI 编程，选择密钥生成 MCP Server 配置，将下方 JSON 配置添加到 IDE 的 MCP 配置文件中，当 API 文档有更新时，Server也会同步更新，提示：必须安装 Node.js 环境（版本号 >= 18.0.0）。": "Boost AIをコーディングし、APIキーを使用してMCP Serverの設定ファイルを生成し、JSONをIDEに追加してください。サーバーはAPIドキュメントの更新と自動同期されます。Node.js 18以上が必要です。",
