  "开启后，当月剩余执行额度为2%时，自动购买100信用点/1万次的单月包，自动从企业账务中心扣除（开启后仍可以在组织管理后台的工作流处关闭）": "有効にすると、月間クォータが2％未満になると、エンタープライズアカウントから100クレジット／10,000実行分のパッケージが自動的に購入されます。（この機能は、Org-Adminのワークフロー設定でいつでも無効化できます。）",
