  "1、每个开票税号开通后，享有 7 天免费试用，到期后自动停用，付费开通后可继续使用": "1. 各税番号には7日間の無料トライアルが付与されます。期間終了後は、有料サブスクリプションを開始するまで利用できなくなります",
