  "开启后，当月剩余执行额度为2%时，自动购买 100信用点/10万行 的单月包，自动从企业账务中心扣除。（开启后可以在数据集成的同步任务中关闭）": "有効化すると、月間実行クォータが2%まで減少した時点で、システムが自動的に10万行ごとに100クレジットのパッケージを購入し、費用はエンタープライズアカウントから差し引かれます。（この機能は、必要に応じてデータ連携の同期タスクで無効化できます。）",
