  "选择充值信用点": "クレジット数を選択",
  "附件可来自用户上传或工作表字段，智能体会将附件内容作为上下文传递给模型。使用该功能可能产生较多费用。图片、PDF 仅能在选择了具备图像识别能力的模型时解析；文档由文档识别服务解析。": "添付ファイルは、ユーザーのアップロードやワークシートのフィールドから追加でき、モデルへのコンテキストとして利用されます。この機能をご利用の場合、追加料金が発生する可能性があります。画像やPDFの解析は画像認識モデルで対応し、ドキュメントはドキュメント認識サービスによって処理されます。",
  "中配置财务角色，并将相关人员加入角色执行审核开票": "財務ロールを設定し、請求およびレビュー担当者を追加します",
