  "用于向使用者介绍应用项的功能、使用方法和注意事项": "アプリの機能、使い方、および注意事項をユーザーに説明するために使用します。",
  "模型将由系统自动选择，当前版本不支持手动修改。消耗Token数将从组织信用点中扣除": "モデルはシステムによって自動選択されます。手動での変更はできません。トークン使用量は組織のクレジットから差し引かれます。",
