  "审批定义": "承認定義",
  "AI 生成": "AIで生成",
  "创建关联表": "関連テーブルを作成",
  "描述智能体的角色、任务目标及注意事项，优质的提示词能显著提升回答准确性。可使用“AI 生成”自动生成": "エージェントの役割、目的、重要なポイントを定義してください。適切に設計されたプロンプトは、応答の精度を大幅に向上させます。「AI生成」を利用すると、自動で提案を受け取ることができます。",
  "创建对话机器人失败": "チャットボットの作成に失敗しました",
  "1年期": "1年間",
  "聚合表无效或已删除": "集計テーブルが無効になっているか、削除されています",
  "查询聚合表": "集計テーブルをクエリ",
  "从聚合表中筛选符合条件的数据并进行汇总计算，如:记录数量、求和、平均、最大、最小等。注意:聚合表的数据有一定延时。": "指定した条件に基づいて集計テーブルのデータをフィルタリングし、レコード数、合計、平均、最大値、最小値などの集計計算を実行します。  \n※集計テーブルのデータには一定の遅延が発生する場合があります。",
  "封装业务流程已删除": "PBPが削除されました",
  "按拼音Z-A排序": "ピンイン順（Z→Aで並び替え）",
