  "%0 模型按 %1信用点 / 1K tokens 计费，自动从企业中心扣除": "%0モデルは1,000トークンごとに%1クレジットで課金され、組織アカウントから自動的に差し引かれます。",
  "1500元/年/税号": "￥1,500／年／税務ID",
  "记忆轮次": "メモリターン",
  "设置后，在扣款时若组织账户信用点低于预警值则会发送预警给通知人（每天仅发送 1 次预警，若重置预警值则会再次发送）": "設定が完了すると、組織のアカウントクレジットがしきい値を下回った場合、指定された受信者に毎日警告が送信されます。しきい値がリセットされると、通知が再開されます。",
  "已添加%0个字段": "%0件のフィールドが追加されました",
  "关注接收全部提醒，默认仅@你/回复时提醒": "フォローしてすべての通知を受け取る（デフォルトでは @メンション／返信のみ）",
  "附件可来自用户上传或工作表字段，智能体会将附件内容作为上下文传递给模型。使用该功能可能产生较多费用。图片、PDF 仅能在选择了具备图像识别能力的模型时解析；文档由文档识别服务解析（0.72 信用点/附件）。": "添付ファイルは、ユーザーのアップロードやワークシートのフィールドから追加でき、モデルのコンテキストとして利用されます。本機能の利用には追加コストが発生する場合があります。画像やPDFは画像認識モデルによって解析され、ドキュメントはドキュメント認識サービス（0.72クレジット／添付ファイル）を通じて処理されます。",
  "创建对话机器人": "チャットボットを作成",
  "如何实现钉钉扫码登录": "DingTalkのQRコードログインを有効にする方法",
  "正在分析图片信息，请稍后。": "情報を処理しています。しばらくお待ちください。",
