  "充值信用点": "クレジットをチャージ",
  "企业微信扫码登录": "WeComのQRコードでログイン",
  "不得与选项列表重复": "既存のオプションと重複しないようにしてください",
  "关注中": "フォロー中",
  "添加工具": "ツールを追加",
  "应用所有工作表": "すべてのワークシート",
  "短信%0/条，自动从企业账务中心扣除。70字计一条短信，超过70字以67字每条计费。每个标点、空格、英文字母都算一个字。短信实际发送可能有10-20分钟的延时。": "メッセージごとに%0が企業アカウントから自動で差し引かれます。SMSは1通につき最大70文字まで送信可能です。これを超える場合、追加のSMSごとに67文字ずつ利用されます。句読点、スペース、英字も1文字としてカウントされます。配信が10〜20分程度遅れる場合があります。",
  "取消勾选，工具执行时将不按用户的数据权限，智能体可访问并返回超出用户本身权限范围的数据。请谨慎使用。": "チェックを外すと、ツールはユーザーデータの権限を無視し、エージェントがユーザーの範囲を超えたデータへアクセス・返却できるようになります。ご利用の際は十分ご注意ください。",
  "输出参数用于定义智能体在执行后输出的结构化字段。你可以添加多个参数并为每个参数编写说明，智能体将根据说明尝试生成结果，供后续流程引用。参数输出结果依赖大模型的理解能力，可能存在失败的情况。": "出力パラメータは、エージェント実行後に返される構造化されたフィールドを定義します。複数のパラメータとその説明を追加でき、エージェントが次のワークフローで利用可能な結果を生成するように誘導します。出力内容はモデルの理解に依存しており、場合によっては変動することがあります。",
  "未查询到记录时": "該当するレコードがありません",
  "从聚合表中筛选符合条件的数据并进行汇总计算，如：记录数量、求和、平均、最大、最小等。注意：当汇总他表字段或者数据频繁变更时可能有一定延时": "集計テーブルから条件に合致するデータを抽出し、件数、合計、平均、最大値、最小値などのサマリーを計算します。  \n※他のテーブルからの集計や頻繁なデータ更新がある場合、処理に時間がかかることがあります。",
  "启用后，待办消息同时会以邮件的形式发送给相关负责人；邮件0.03信用点/封，自动从账务中心扣费": "有効化すると、ToDo通知が担当者にメールで送信されます。1通につき0.03クレジットが自動的にビジネスアカウントから差し引かれます。",
