  "日%25011": "日",
  "系统处理异常，未返回有效内容": "システム処理エラーが発生しました。有効なコンテンツが返されませんでした。",
  "用于工作流邮件节点或外部门户发送邮件，费用0.03元/封": "ワークフローのメールノードや外部ポータルを通じてメール送信に使用されます。1通あたり¥0.03の料金が発生します。",
