  "只勾选微信登录时首次扫码后需要输入手机号与微信绑定，后续可单独微信扫码快速登录。发送验证码的短信或邮件费用将自动从组织信用点中扣除。": "WeChatログインを選択した場合、初回のスキャン時にユーザーはWeChatに携帯電話番号を連携する必要があります。以降は、WeChatのスキャンで迅速にログインできます。SMSやメールによる認証コードの送信にかかる費用は、組織のクレジットから差し引かれます。",
