  "描述你希望 AI 动作实现的目标和功能。例如：“依据当前客户记录生成跟进建议”": "AIアクションで達成したい結果を入力してください（例：「顧客記録に基づきフォローアップを提案する」）。",
  "AI 将根据您的描述自动生成AI 动作的名称以及提示词 ”": "AIが説明に基づいてアクション名とプロンプトを自動生成します",
