  "将复制目标AI 动作的所有节点和配置": "対象AIアクションのすべてのノードと設定をコピー",
  "AI 动作用于在记录上下文中解决特定业务场景的问题，例如生成总结、分析讨论内容、给出行动建议或产出沟通文案": "AIアクションを特定の業務シナリオに適用できます。たとえば、要約の生成、議論の分析、アクションの提案、コミュニケーション内容の下書き作成などが可能です",
  "您可以点击右上角添加AI 动作，AI 动作将显示在记录页右侧，供用户点击触发": "レコードページの右上をクリックすると、AIアクションを追加できます",
  "AI 动作用于在记录上下文中解决特定业务场景的问题，例如分析讨论内容、给出行动建议或产出沟通文案；AI 动作将显示在记录页右侧，供用户点击触发": "AIアクションをレコードに適用し、ディスカッションの分析、アクションの提案、コミュニケーションの下書きなど、特定のビジネスシナリオに対応できます。これらのオプションは、レコードページの右側に表示され、ユーザーが実行できます。",
