  "您确定要变更电子开票授权吗？": "電子インボイス認証の変更を確認しますか？",
  "关闭电子开票节点授权或调整授权范围后，未获授权应用中已配置电子开票节点的工作流将无法使用当前开票税号开具电子发票。": "e-invoiceノードの認可が無効化されるか、またはスコープが変更された場合、認可されていないアプリに連携しているワークフローでは、現在の税務IDを用いた電子インボイス発行ができなくなります。",
  "自动开票配置": "自動請求書設定",
  "电子开票节点授权": "電子インボイスノード認可",
  "开启后，当前开票税号可在所授权应用的工作流【电子开票】节点中使用，由系统自动开具发票，无需管理员人工审核；未授权应用的工作流电子开票节点将无法使用当前开票税号。": "有効化すると、現在の税務IDは認可されたアプリの電子インボイス発行にのみ使用できます。請求書は管理者の確認なしで自動的に発行され、認可されていないアプリではこの税務IDを利用できません。",
