  "当成员未命中其他策略时将正常访问其有权限的全部应用。建议创建禁止访问应用的策略，限制特定访问场景": "他のポリシーが適用されていないメンバーは、許可されたすべてのアプリに通常通りアクセスできます。特定のアクセスシナリオを制限する場合は、アクセス拒否ポリシーを作成してください。",
