  "Web移动端通常建议勾选此配置，可以加快图片上传速度并节省流量。未勾选时，将始终按照原图上传。（此配置影响：原生H5、公开表单、外部门户，以及第三方平台的移动App）": "画像のアップロードを高速化し、データ通信量を節約するために、このオプションの有効化を推奨します。無効にした場合、画像は元のサイズのままアップロードされます（対象：ネイティブH5、公開フォーム、外部ポータル、サードパーティ製モバイルアプリ）。",
  "字段显示": "フィールドを表示",
