  "掩盖规则的优先级高于开头显示、结尾显示和中间显示。": "マスキングルールは、先頭・末尾・中間での表示設定よりも優先されます。",
  "输入隐藏的字符，多个使用,隔开。如：a,b,c": "非表示文字をカンマ区切りで入力してください（例：a,b,c）",
