  "支付订单退款": "返金注文",
  "为记录关联的支付订单自动进行退款": "自動返金済みの連携支払い注文",
  "组织后台上传的商品管理表中的税收服务简称": "Org-Adminでアップロードされたプロダクト管理シート内の税務サービス略称",
  "发票抬头类型为企业时，税号字段不能为空，否则无法开票": "会社請求書には税務番号が必要です",
  "接收电子发票的购方邮箱": "電子請求書送付先メールアドレス",
  "本节点使用前，请确保已开通开票税号。电子开票采用异步处理方式，节点执行时将等待开票结果，开票完成后再继续后续流程。该开票为自动操作，无需管理员审核。": "このノードを使用する前に、請求用税IDが有効化されていることを確認してください。電子インボイスは非同期で処理され、有効化完了後に自動で進行します。管理者の承認は不要です。",
  "前往组织后台开通": "「組織ダッシュボードへ進み、アクティベートしてください」",
  "开票税号未授权，请": "税IDが承認されていません、",
  "系统将退还该订单已支付的全部金额": "本システムは本注文を全額返金します",
  "前往组织后台授权": "組織管理者による承認に進む",
  "部分退款金额(动态值)不得大于订单实付金额": "部分返金額（動的値）は、支払い済み注文金額を超えることはできません。",
  "系统将根据当前节点的记录对象，自动对其关联的支付订单发起退款（仅支持已产生支付订单的记录）；当退款金额大于订单实付金额时，本节点将自动跳过，不发起退款。": "システムは、現在のノードにおける決済済みの注文に対して、自動的に返金処理を開始します。返金額が実際の支払金額を超える場合は、返金処理はスキップされます。",
  "选择退款对象": "返金受取人を選択",
  "部分退款金额不能为空": "部分返金額を入力してください",
  "向 Agent 提供": "エージェントに提供",
  "用户在对话中发送的消息和附件将作为上下文提供给 AI Agent": "メッセージおよび添付ファイルがAIエージェントのコンテキストとして使用されます",
  "向 Agent 提供当前记录": "エージェントに〜を提供",
  "勾选后，系统会将整条记录的字段信息提供给 AI Agent": "選択すると、システムはレコードのすべてのフィールドデータをAIエージェントに提供します",
  "勾选后，系统会将当前记录的最近50条讨论信息提供给 AI Agent": "選択すると、システムはAIエージェントに最新のディスカッション記録50件を提供します。",
  "讨论信息": "コメント情報",
  "非图片类附件会先进行文本解析（免费），解析结果将作为上下文发送给模型，可能增加 Token 消耗。图片附件将直接发送给模型处理，是否可识别取决于所选模型是否支持图片理解": "画像以外の添付ファイルは無料でテキストに変換され、コンテキストとして使用されます。そのため、トークンの使用量が増加する可能性があります。画像ファイルは直接モデルに送信され、画像認識の可否はモデルの画像理解機能に依存します。",
  "节点加签后更新": "ノードの共同署名後に更新",
