  "%0账号与平台账号解绑后，将不能通过平台官网登录": "アカウント %0 の連携を解除すると、公式ウェブサイトからログインできなくなります。",
  "；后续点击同步可以重新选择账号绑定。": "、「同期」をクリックしてアカウントを再連携します。",
