  "一键复用": "すべてに適用",
  "上传多个应用文件，实现多个应用整体升级。最多上传%0个文件。应用升级需要一段时间，正在升级中的应用将为不可用状态。": "アプリファイルを一括アップロードしてまとめてアップグレードします（最大%0ファイルまで）。処理中はアプリをご利用いただけません。",
  "上传迁移包后系统将自动匹配应用：若已存在则全量覆盖更新完成迁移，若不存在则创建新应用；注意：迁移应用在全平台仅能存在一个。": "マイグレーションパッケージをアップロードすると、システムがアプリを自動的に照合します。既存のアプリは更新され、新規のアプリは作成されます。\n\n※プラットフォーム上には、マイグレーションアプリは1つのみ存在できます。",
  "自动匹配应用，不存在则按原 ID 创建新应用，存在则按相同 ID 全量覆盖更新。注意：迁移模式下应用在全平台仅能存在一个": "アプリケーションの自動マッチング：既存のアプリケーションがない場合は、元のIDで新規作成します。既存の場合は、同じIDに基づいて完全に上書きします。  \n注意：マイグレーションモードでは、アプリケーションは1つのプラットフォームにのみ存在できます。",
