  "用户可在下拉列表中查看更多记录信息": "ドロップダウンで詳細を表示",
  "允许弹层选择": "ポップアップを有効にする",
  "在下拉框中显示弹层选择按钮，用户点击后可打开表格弹层选择记录。弹层可设置更多显示字段和筛选器": "ドロップダウン内にポップアップボタンを表示し、拡張フィールドおよび高度なフィルターを備えたレコード選択テーブルを開きます",
