  "选择已认证主体": "認証済みエンティティを選択",
  "请使用企业简称或注册商标作为短信签名；提交后需运营商审核，预计 1–3 个工作日，审核通过前该签名不可使用；签名需不少于 2 个字符且不得包含特殊符号": "SMS署名には、会社の略称または登録商標をご利用ください。  \nキャリア審査には1～3営業日かかります。  \n承認前の署名は使用できません。  \n署名は2文字以上、記号は使用できません。",
  "，详细要求请参考：": "、詳細については、こちらをご参照ください:",
  "签名命名规范": "署名の命名ルール",
  "签名请使用您的公司简称或者商标名称；审核中的签名不能使用，签名需不少于 2 个字符且不得包含特殊符号。": "署名は、会社の略称または商標名を使用してください。  \n審査中の署名は使用できません。  \n署名は2文字以上で、特殊記号は使用できません。",
  "可通过发送一条短信来测试当前签名是否可以正常使用，短信发送后会自动扣费": "署名の有効性を確認するためにテストSMSを送信します。送信後は料金が発生します。",
