  "可在 Microsoft Entra 后台创建一个安全组，并将需要同步到平台的成员加入该组，平台后续仅同步该安全组内的用户及其相关信息；如不填写安全组（GroupID 为空），则默认同步目录下的全部成员。": "Microsoft Entra管理センターでセキュリティグループを作成し、プラットフォームと同期するメンバーを追加します。  \nこのグループ内のユーザーと情報のみが同期されます。セキュリティグループが指定されていない場合（GroupIDが空の場合）、ディレクトリ内のすべてのメンバーが同期されます。",
  "参考帮助文档": "ヘルプを",
  "查看帮助文档": "ヘルプを",
  "（已过期）": "（期限切れ）",
  "为记录提供上下文感知的智能操作，支持内容生成与工具调用。添加后将显示在记录详情页，供用户一键触发": "レコード内容に基づいてインテリジェントなアクションを提供し、コンテンツ生成やツール呼び出しをサポートします。レコード詳細ページからワンクリックで実行できます。",
  "请使用企业简称或注册商标作为短信签名；提交后需运营商审核，预计 1–3 个工作日，审核通过前该签名不可使用；签名需不少于 2 个字符且不得包含特殊符号。": "SMS署名には、会社の略称または登録商標をご利用ください。  \nキャリア審査には1～3営業日かかります。  \n承認前の署名は使用できません。  \n署名は2文字以上、記号は使用できません。",
