  "仅支持IPv4，可输入IP地址或CIDR格式的IP地址段": "IPv4のみ対応しています。IPアドレスまたはCIDR範囲を入力してください。",
  "基于上下文提供智能操作，支持内容生成与工具调用，高效处理任务": "コンテンツ生成とツール呼び出しによるスマートアクションで、業務を効率的に処理できます",
  "添加后将显示在记录详情页，支持一键触发": "追加後、レコード詳細ページでワンクリックでトリガーできます",
  "注意️：若节点状态一直是进行中，请检查数电账号是否已登录或者是否已完成人脸识别。": "注意: ノードのステータスが「進行中」のままの場合は、Digital Accountにログインしているか、顔認証が完了しているかをご確認ください。",
  "请使用企业简称或注册商标作为短信签名；提交后需运营商审核，预计 5-10 个工作日，审核通过前该签名不可使用；签名需不少于 2 个字符且不得包含特殊符号。": "SMS署名には、会社の略称または登録商標をご利用ください。  \nキャリア審査には5～10営業日かかります。  \n承認前の署名は使用できません。  \n署名は2文字以上、記号は使用できません。",
  "试用、免费版需组织完成身份认证后可充值信用点；对外分享、自定义短信签名等功能需完成组织身份认证（注意：非个人身份）": "トライアル版および無料版でクレジットをチャージするには、組織の認証が必要です。  \n外部共有およびカスタムSMS署名の利用には、組織認証が必要です。",
