  "支持导入姓名、手机号、邮箱、工号、人员ID。手机号前缀需要附带国家代码以及+号, 例如美国号码：+1**********": "氏名、携帯番号、メールアドレス、従業員ID、ユーザーIDのインポートに対応しています。  \n携帯番号は、国番号（+記号付き）を含めて入力してください。例：米国の場合「+1**********」",
  "为关联记录、级联选择、成员、部门等字段额外导出一列ID，便于后续按 ID 精确匹配导入数据": "関連レコード、カスケード選択、メンバー、部署などのフィールドにID列を追加し、データインポート時の正確なマッチングを実現します。",
