  "仅支持选择自定义打印模板（Word 或 Excel），暂不支持使用系统模板": "カスタム印刷テンプレート（WordまたはExcel）の選択のみサポートされており、システムテンプレートはサポートされていません。",
  "在人员选择层、通讯录中按部门查看时，按设置的排序显示": "人員選択レイヤーおよびアドレス帳で部門別に表示する際、設定された並び順で表示します",
  "9. 时间类型字段默认按照 yyyy-MM-dd HH:mm:ss（2025-01-01 12:00:00） 格式打印。可在字段代码后拼接格式代码来自定义打印时的方式。例：将#{ctime}拼接为#{ctime$[yyyy/M/d]$}，则创建时间打印为：2025/1/1。": "9. 時間タイプのフィールドは、デフォルトで yyyy-MM-dd HH:mm:ss（2025-01-01 12:00:00）形式で印刷されます。フィールドコードの後にフォーマットコードを追加することで、印刷時の方法をカスタマイズできます。例：#{ctime}を#{ctime$[yyyy/M/d]$}として追加すると、作成日時が次のように印刷されます：2025/1/1。",
