  "每月 1,000 次工作流执行": "毎月 1,000 件のワークフロー実行",
  "签名规范：签名内容长度为2-20个字；由中英文组成，不能纯英文；签名内容必须能辨别所属公司名称或品牌名称；不符合规范的签名平台会清空需重新输入，同时运营商也会拦截。": "サインの規範：サインの内容の長さは2〜20文字でなければならない；中英文の組み合わせで、英語のみではならない；サインの内容は関連する会社名またはブランド名を識別できなければならない；規範に合わないサインはプラットフォームによってクリアされ、再入力が必要になる。また、運営者もそれを遮断する。",
  "通过首要按钮来强调主要操作。如：设置1个首要按钮，则第一个按钮显示为实心颜色。其他按钮则被显示为空心线框": "主要な操作を強調するために、プライマリーボタンを使用します。たとえば、1つのプライマリーボタンを設定すると、最初のボタンが実線の色で表示されます。他のボタンは空の線で囲まれた形で表示されます。",
