  "编辑自定义动作": "カスタムアクションを編集",
  "添加后，支持设置部门对应的职位信息，设置后在成员的个人资料中展示。原本的“职位”将显示为“全部职位”汇总多任职信息中的职位信息，并在系统中使用。": "複数の役職を設定し、それに対応する情報をプロフィール名刺に表示できます。\n元の「役職」フィールドは、複数の役職が追加されると「すべての役職」として表示されます。",
  "4. 可获取附件字段中的图片缩略图和文件名。字段代码为：#{附件$[90*auto_L]$_name}。其中：90*auto 表示图片宽/高尺寸（单位mm）；_L表示获取的图片质量；_name表示获取文件名。": "4. 添付ファイルフィールドの画像のサムネイルとファイル名を取得できます。\nフィールドコード：#{Attachment$[90*auto_L]$_name}\nここで、90*auto は画像の幅・高さ（単位：mm）、_L は画質、_name はファイル名を示します。",
