  "开启后，应用管理员、运营者可以使用不同的角色身份访问应用。开发者暂不支持使用此功能。": "有効にすると、アプリケーション管理者とオペレーターは異なる役割の身分でアプリケーションにアクセスできます。開発者はこの機能を使用することはできません。",
