  "编辑 Basic Auth 测试数据": "Basic Auth テストデータを編集",
  "开启后可上传附件。使用该功能可能产生较多费用。为保证体验，请选择上下文长度较大的模型。图片和PDF 由模型解析（需在 AI 智能体节点配置具备图像识别能力的模型）；文档由文档识别服务解析（0.72 信用点/附件）": "添付ファイルのアップロードを有効にします。ご利用状況によっては追加費用が発生する場合があります。より快適にご利用いただくためには、より大きなコンテキスト長を持つモデルのご利用をおすすめします。画像やPDFファイルにはOCR機能対応モデル（AIエージェントノードで設定）が必要です。ドキュメントはドキュメント認識サービスによって処理されます（0.72クレジット/添付ファイル）。",
