  "1.支付功能服务费：按商户号收取，年费999元/商户，月费199元/商户；新商户可申请一周免费试用，试用期间单笔订单限额1元。": "1. 支払い機能サービス料：マーチャント番号に応じて請求され、年額999元/マーチャント、月額199元/マーチャント；新規マーチャントは1週間の無料トライアルを申請でき、トライアル期間中は単一注文の制限が1元です。",
  "只有能访问该视图的用户，才能看到并使用配置的快速筛选": "このビューにアクセスできるユーザーのみが、設定されたクイックフィルターを表示および使用できます。",
  "是否物理删除(true：物理删除，false：逻辑删除，默认为false)，物理删除后数据不进入回收站，且不可恢复，请谨慎操作！": "物理削除にしますか (true: 物理削除、false: 論理削除、デフォルトはfalse)？物理削除後、データはゴミ箱に入らず、復元できませんので、ご注意ください。",
  "设置应用、工作表消耗的服务资源额度上限。可全局配置额度，也可以单独设置": "アプリケーションとワークシートが消費するサービスリソースの上限を設定します。クォータはグローバルに設定することも、個別に設定することもできます。",
