  "设置一天内每个应用的工作流执行次数上限。可为所有应用全局配置，也可以为特殊的应用单独设置。": "1日内に各アプリケーションのワークシート実行回数の上限を設定します。すべてのアプリケーションに対してグローバルに設定することも、特定のアプリケーションに対して個別に設定することもできます。",
