  "（3）默认代码中不包含文件名，需要时可自行拼接_name。例如：#{附件$[90*auto_L]$_name}表示同时获取图片缩略图和文件名；#{附件_name}表示只获取文件名。备注：Excel模版不支持图片与文件名同步显示。": "（3）デフォルトではファイル名は含まれません。ファイル名を表示するには _name を追加してください。\n例：#{attachment$[90*auto_L]$_name} は画像とファイル名を表示、#{attachment_name} はファイル名のみを表示します。Excelテンプレートでは画像とファイル名を同時に表示できません。",
  "我可以为您解析文字或图片内容，智能填写到表单字段": "テキストや画像の解析に対応し、フォーム項目を自動入力します",
