  "添加多任职信息": "複数の役職を追加",
  "满足条件时，将在记录保存后生效锁定。锁定记录无法被编辑或删除，仅应用管理员可解锁记录。只能添加一条锁定规则。": "条件が満たされた場合、記録保存後にロックが発効します。ロックされた記録は編集・削除不可となり、アプリ管理者のみがロック解除可能です。ロックルールは1つのみ追加可能です。",
  "开启后，Web 端可使用SSO登录。当用户通过SSO完成登录后，在退出登录时将会被重定向回SSO登录页": "有効にすると、Web版でSSOログインを使用できます。ユーザーがSSOを通じてログインを完了すると、ログアウト時にSSOログインページにリダイレクトされます。",
