  "确保连接数据库时的账号具有当前数据库的 db_owner 或以上权限": "データベースに接続する際には、アカウントが現在のデータベースの db_owner 以上の権限を持っていることを確認してください。",
  "名称和说明": "名前と説明",
  "新版对记录详情界面进行了重构，如遇问题，可点击按钮返回旧版本。": "レコード詳細が更新されました。必要なら旧バージョンに戻せます。",
