  "设置每个工作表行记录数量上限。可为所有工作表全局配置，也可以为特殊的工作表单独设置。组织可设置最大上限为 100万行 / 每个表": "各ワークシートの行記録数の上限を設定します。すべてのワークシートに対してグローバルに設定することも、特定のワークシートに対して個別に設定することもできます。組織は、各表に対して最大100万行を設定できます。",
