  "关闭超过90天的组织，所有应用已自动进入回收站，进入回收站60天后，所有应用会被彻底物理删除": "90日以上活動していない組織を閉鎖します。すべてのアプリケーションは自動的にゴミ箱に移動されます。ゴミ箱に60日間保存された後、すべてのアプリケーションは完全に削除されます。",
  "请上传您有效的组织相关证书，以及与证书一致的法人身份证人像面与国徽面，并输入与身份证一致的实名制手机号，系统会自动进行匹配认证并保证您的隐私安全，若信息正确但未能有效通过认证，可联系在线客服或专属顾问": "有効な組織関連証明書と証明書に一致する法人の身分証明書の表面と国章面をアップロードしてください。また、身分証明書に一致する実名制の携帯番号を入力してください。システムは自動的に照合認証を行い、あなたのプライバシーを安全に保ちます。情報が正しいにもかかわらず認証に失敗した場合は、オンラインカスタマーサービスまたは専属コンサルタントにお問い合わせください。",
