  "根据当前流程节点中的记录对象，生成特定的对外分享链接或内部链接。内部链接仅在登录后并有权限时可以查看。可以通过在邮件、短信的正文里引用此节点，邀请外部用户查看或填写指定的记录。": "現在のレコードに基づき、外部共有リンクまたは内部リンクを生成します。内部リンクはログインと権限が必要です。このノードをメールやSMSで使い、外部ユーザーにレコードの閲覧や入力を依頼できます。",
