  "多任职信息中可以设置部门对应的职位，并在成员的个人资料中展示对应关系。原本的“职位”将显示为“全部职位”汇总任职信息中的职位信息并在系统中使用，在多任职中添加职位、会填入“全部职位”中。": "複数の役職を設定し、それに対応する情報をプロフィール名刺に表示できます。\n元の「役職」フィールドは、複数の役職が追加されると「すべての役職」として表示されます。",
  "任职信息%0": "職務 %0",
