  "通过组织认证方可添加自定义签名，并使用您的公司简称或者商标名称。自定义签名到达率受运营商风控等因素影响，若实际到达率不佳，建议您可以尝试切换到平台默认提供的签名。具体命名规范参考：": "組織認証を受けた後にのみ、カスタム署名を追加でき、会社の略称または商標名を使用します。カスタム署名の到達率は、キャリアのリスク管理などの要因に影響を受けます。実際の到達率が良くない場合は、プラットフォームが提供するデフォルトの署名に切り替えることをお勧めします。具体的な命名規範は次のとおりです:",
