  "说明配置": "設定手順",
  "1、平台按照商户号收取支付功能服务费，您可申请一周的免费试用，试用期内单笔订单交易额最高为 1元，收费标准：999元/商户/年（年费）199元/商户/月（月费）": "1、プラットフォームは、マーチャント番号に基づいて支払い機能のサービス料金を請求します。1週間の無料トライアルを申請できます。トライアル期間中の1件の注文の取引額の上限は1元です。料金基準は：999元/マーチャント/年（年会費）、199元/マーチャント/月（月会費）",
