  "签名内容长度为2-20个字；由中英文组成，不能纯英文；签名内容必须能辨别所属公司名称或品牌名称；不符合规范的签名平台会清空需重新输入，同时运营商也会拦截。签名必须线下完成实名登记，且一个营业执照只能设置一个签名。": "署名は2 - 20文字で、中国語と英語を含み（英語のみ不可）、関連会社やブランドを識別できるものでなければなりません。不適合な署名はプラットフォームで削除され再入力が求められ、オペレーターも阻止します。実名でオフライン登録し、1営業許可証につき1署名です。",
  "超时前显示倒计时": "タイムアウト前にカウントダウンを表示する",
  "用于工作流短信节点或外部门户短信邀请，费用0.05信用点/条": "ワークフローのSMSノードや外部ポータルへのSMS招待に使用されます。1メッセージにつき0.05クレジットが課金されます。",
