  "此签名适用的短信场景:外部门户用户注册登录、邀请外部用户注册、外部用户审核(通过/拒绝);修改签名必须线下完成实名登记，且一个营业执照只能设置一个签名。": "この署名は、外部ポータルのユーザー登録・ログイン、外部ユーザー招待、審査（承認/却下）のSMSに使用可能。変更時は実名でオフライン登録が必要で、1営業許可証につき1署名まで。",
