  "视图别名仅允许使用字母（不区分大小写）、数字和下划线组合，且必须以字母开头，不可重复。": "ビュー エイリアスは文字で始まり、文字 (大文字と小文字は区別されません)、数字、またはアンダースコアのみを含める必要があります。",
