  "type：控件类型，目前支持控件类型有 2:文本、6:数值、9:单选、10:多选、46:时间、15:日期（年-月-日）、16:日期 （年-月-日 时:分）、26:成员、14:附件、29:关联记录": "タイプ：コントロールの種類、現在サポートされているコントロールの種類は 2:テキスト、6:数値、9:単選択、10:複数選択、46:時間、15:日付（年-月-日）、16:日付（年-月-日 時:分）、26:メンバー、14:添付ファイル、29:関連レコード",
