  "开启后，不能多人同时编辑同一条记录。当有用户在详情页触发编辑时，该记录即进入保护状态，仅当前用户可编辑记录，其他用户仅能查看。当该用户提交记录或超过保护时长，其他用户方可编辑。": "有効にすると、一度に一人のユーザーだけがレコードを編集できます。ユーザーが詳細ページで編集を開始すると、そのレコードは保護され、他のユーザーは変更できなくなります。現在のユーザーが送信するか、保護期間が終了するまで、他のユーザーは閲覧のみ可能です。",
  "格式:YYYY-MM-DD HH:mm:ss,为空表示永久有效": "形式: YYYY-MM-DD HH:mm:ss、空の値は常に有効です",
  "（5）序号打印：如果需要在子表、关联记录、查询记录（列表）中打印系统自动生成的序号字段，可在代码中调用 sequencenumber 字段代码，例如 #{关联表字段代码.sequencenumber}。其中“关联表字段代码”为当前表中关联字段的字段代码，sequencenumber 为系统自动编号字段的固定代码": "(5) 連番印刷： サブテーブル、関連レコード、検索結果（一覧）でシステム自動生成の連番を印刷する場合、コード内で sequencenumber フィールドを呼び出します。例：#{関連テーブルフィールドコード.sequencenumber}。ここで「関連テーブルフィールドコード」は現在のテーブルの関連フィールドコード、「sequencenumber」はシステム固定の自動連番コードです。",
