  "主属部门": "主部門",
  "本文档提供了一个简单的方法来实现实现应用数据和任何外部数据的集成。API严格遵循REST语义，使用JSON编码对象，并依赖标准HTTP代码来指示操作结果。": "このドキュメントは、アプリケーションデータと任意の外部データの統合を実現するための簡単な方法を提供します。APIはRESTセマンティクスに厳密に従い、JSONでエンコードされたオブジェクトを使用し、操作結果を示すために標準のHTTPコードに依存しています。",
