  "移动端支持扫码查询": "モバイル端末でのQRコード問い合わせサポート",
  "1.函数返回值需要保证和当前子表的数据结构完全一致，从而对子表数据进行全量替换更新。否则将会导致未知异常问题。\\n\\n2.此功能仅提供给熟悉代码的用户使用，可以自由处理子表数据实现复杂业务逻辑。普通用户请谨慎使用！\\n\\n%0": "1. 関数の戻り値は、現在のサブテーブルのデータ構造と完全に一致することを保証しなければなりません。そうでないと、未知の例外問題が発生する可能性があります。\n\n2.この機能は、コードに精通しているユーザーのみが使用できます。サブテーブルのデータを自由に処理して複雑なビジネスロジックを実現できます。一般のユーザーは注意して使用してください！",
  "添加字段 Ctrl+/": "フィールドを追加 Ctrl+/",
  "预置提问最多设置5个": "最大5件までのプリセット質問を設定できます",
  "查看个人资料": "プロフィールを見る",
