  "成员信息显示": "メンバー情報の表示",
  "智能体每次执行时接收的原始内容，通常来自用户消息或流程变量，作为模型生成回复的基础内容": "エージェントは毎回、ユーザーメッセージやフロー変数などの入力をもとに応答を生成します",
  "（4）在打印 Excel 模板时，多张图片排列可能导致撑高合并单元格引起错位，此时可以加 F 启用图片填充模式，此模式下图片不会撑高单元格，例如：#{附件$[auto*20_F]$} 或 #{附件$[auto*90_HF]$}": "（4）Excelテンプレートを印刷する際、複数の画像を配置すると、セルが引き伸ばされ、結合セルがずれる場合があります。その場合は Fキー を押して「フィルモード」を有効にすると、画像によるセルの高さ変更を防げます。例：#{attachment$[auto*20_F]$} または #{attachment$[auto*90_HF]$}",
  "讨论内容": "議論内容",
  "暂无权限联系该用户": "このユーザーに連絡する権限がありません",
  "邮件收费标准：邮件%0/封，自动从企业账务中心扣除。": "メール料金：1通あたり%0、エンタープライズアカウントから自動で差し引かれます。",
  "附件默认旧文件在前，可拖拽调整顺序，但新上传文件仍会按默认规则排序": "添付ファイルはデフォルトで古いファイルが前に来ます。ドラッグして順序を調整できますが、新しくアップロードされたファイルは依然としてデフォルトのルールに従って並べ替えられます。",
