  "允许将记录对外公开分享，获得链接的所有人都可以查看记录": "公開共有を許可すると、リンクを知っている人なら誰でも記録を閲覧できます",
  "AI只填写输入内容中明确包含的字段": "AIは、入力で明示的に指定された項目のみを自動入力します",
  "3、微信支付/支付宝支付直连的商户号提现只能在微信支付商户后台、支付宝商户平台操作": "3. WeChat Pay/Alipayに直接接続されたマーチャント番号の出金は、WeChat PayのマーチャントバックエンドおよびAlipayのマーチャントプラットフォームでのみ操作できます。",
  "国家": "国",
