  "是否取消当前订单": "この注文をキャンセルする",
  "%0已锁定，无法保存%1": "%0はロックされていて、%1を保存できません",
  "基于应用成员协作便利考量，若在讨论中 @用户，则表示期望被 @者知晓当前数据。此时即便被 @人无当前视图或记录权限，只要拥有工作表权限，就能通过消息链接以只读形式查看记录。": "コラボレーションを円滑にするため、ディスカッション内で @user をメンションすると、該当データに関する通知が送信されます。テーブルへのアクセス権があれば、現在のビューやレコード権限がなくても、メッセージ内のリンクからレコードを閲覧専用モードで確認できます。",
  "显示收藏的应用": "お気に入りのアプリを表示",
  "系统将不再定期备份您的应用数据": "アプリデータの定期バックアップは停止されます。",
  "开票测试说明：本操作将生成个人抬头的正式发票（非演示票），发票会入账并发送至你指定的邮箱。如不需要，请及时在电子税务局/百望进行红冲或作废": "請求書テスト手順：この操作により、あなた名義の正式な請求書が発行されます。請求書はアカウントに追加され、ご登録のメールアドレス宛に送信されます。不要な場合は、電子税務局または百望（Baiwang）から速やかにキャンセルしてください。",
  "获得链接的人可以查看记录详情，需点击支付按钮生成支付订单后进行付款": "閲覧者はレコードの詳細を確認し、［支払い］ボタンから支払い注文を作成できます",
  "1.函数返回值需要保证和当前子表的数据结构完全一致，从而对子表数据进行全量替换更新。否则将会导致未知异常问题。%02.此功能仅提供给熟悉代码的用户使用，可以自由处理子表数据实现复杂业务逻辑。普通用户请谨慎使用！%1": "1. 関数の戻り値は、現在のサブテーブルのデータ構造と完全に一致する必要があり、サブテーブルデータの完全置換更新を行います。さもなければ、未知のエラーが発生する可能性があります。%02. この機能は、コードに精通したユーザーにのみ提供されており、サブテーブルデータを自由に操作して複雑なビジネスロジックを実現できます。一般ユーザーは慎重に使用してください！%1",
  "创建自动化工作流": "自動化ワークフローを作成する",
  "未开启时，按关联记录本身设置；开启后可配置细分操作": "オフの時は関連レコードの設定を使用し、オンの時は詳細な操作を設定できます",
  "删除成功，锁定或无删除权限的记录已被忽略": "削除に成功しました。ロックされているか、削除権限がないレコードは無視されました。",
  "仅详情页内编辑才能生效编辑保护；": "詳細ページ内で編集している場合にのみ編集保護が有効になります。",
