  "可将指定应用内的所有工作表数据存储到专属数据库中，免受系统默认数据库的影响，适用于隔离等场景，当前支持最多创建%0个可用专属数据库实例；管理员创建应用时，可选择专属数据库。": "指定したアプリケーション内のすべてのワークシートデータを専用データベースに保存でき、システムのデフォルトデータベースの影響を受けず、隔離などのシナリオに適しています。現在、最大で %0 の専用データベースインスタンスを作成できます。管理者はアプリケーションを作成するときに専用データベースを選択できます。",
