  "试用、免费版需组织完成身份认证后可充值余额；自定义短信签名需组织完成企业身份认证（注意：非个人身份）": "無料版/トライアル版で本人確認を完了すると、リチャージが解除されます。カスタムSMS署名には、個人ではなく組織の認証が必要です。",
