  "当前用户数已超出人数限制": "現在のユーザー数は制限を超えています。",
  "当输出参数是“对象数组”时，可以在流程中使用“获取数组对象”节点将发送 API 请求、JSON 解析或代码块节点中返回的数组参数转为多条数据对象，之后可以在对象数组输出参数的子元素中设置值为数组中的对象元素字段。当输出参数是“普通数组”时，可以使用“JSON 解析”节点中输出的“普通数组”作为参数值。": "出力パラメータが「オブジェクト配列」の場合、フロー内で「配列オブジェクトを取得」ノードを使用して、APIリクエスト、JSON解析、またはコードブロックノードから返される配列パラメータを複数のデータオブジェクトに変換できます。その後、オブジェクト配列出力パラメータのサブ要素に配列内のオブジェクト要素のフィールドを値として設定できます。出力パラメータが「通常の配列」の場合、「JSON 解析」ノードから出力された「通常の配列」をパラメータ値として使用できます。",
  "业务规则条件引用": "ビジネスルール条件参照",
  "微信支付商户平台": "WeChat Payのマーチャントプラットフォーム",
