  "1.根据平台部署情况选择": "1. プラットフォームの展開状況に基づいて選択",
  "委托范围": "委託範囲",
  "请选择对应视图": "対応するビューを選択してください",
  "组件支持 Tailwind CSS 你可以直接使用，组件内已经预置了 lucide icons，用法与官方稍微有些不同，需要使用 `LucideIcon` 组件，name 是具体的图标名称。名称是大驼峰写法，你可以在 [这里][1] 找到，其他属性和 `lucide-react` 一致。": "コンポーネントは Tailwind CSS をサポートしており、直接使用できます。コンポーネントには既に lucide icons がプリセットされており、使用法は公式とわずかに異なり、`LucideIcon` コンポーネントを使用する必要があります。名前は大文字と小文字を区別したキャメルケースで書かれており、[こちら][1] で見つけることができます。他の属性は `lucide-react` と一致しています。",
