  "支付宝支付；费率参考支付宝支付官方规则": "アリペイ決済；手数料はアリペイ決済の公式ルールを参照",
  "存储类型接收 `value` 和 `onChange`，`value`是当前字段的值，处理好值后可以调用`onChange`来更新值。": "ストレージタイプは `value` と `onChange` を受け取ります。 `value` は現在のフィールドの値であり、値を処理した後、`onChange` を呼び出して値を更新できます。",
