  "示例：=SUBSTITUTE(\"a a b b b c\", \"b\", \"B\") 返回\"a a B B B c\"": "例：=SUBSTITUTE(\"a a b b b c\", \"b\", \"B\") は \"a a B B B c\" を返します",
  "填写的密钥、证书等信息采用动态加密存储，保存之后掩码显示，保证您的信息安全": "入力されたキー、証明書などの情報は動的暗号化ストレージを使用して保存され、保存後はマスク表示されて情報の安全性が保証されます。",
  "中设置APIv2密钥。密钥为32位，推荐使用搜索引擎（如百度）搜索内容：在线密码生成器生成，例如「随机密码生成器」，自己编写密钥无法发起支付。": "中にAPIv2キーを設定します。キーは32文字で、オンラインパスワードジェネレーターを生成するために検索エンジン（百度など）を使用することをお勧めします。「ランダムパスワードジェネレーター」など。自分でキーを作成することは、支払いを開始しません。",
