  "示例：=ACOT(1) 将返回弧度为 0.785398163397448 的角度（45 度），其正切值为 1。": "例：=ACOT(1)は、0.785398163397448ラジアン（45度）の角度を返し、そのタンジェント値は1です。",
  "3、密钥、证书等字段信息采用动态加密存储，保存后掩码显示，保障信息安全": "3. 秘密鍵や証明書などのフィールド情報は動的暗号化されて保存され、保存後はマスク表示されるため、情報の安全が保証されます。",
  "当前用户数已经达到限额，请去购买": "現在のユーザー数は上限に達しましたので、購入してください",
