  "当未设自定义排序，或自定义排序后同顺序下有多条记录时，将追加使用默认排序。默认排序只能使用创建时间或最近更新时间，来确保数据最终有严格顺序。": "カスタムソートが設定されていない場合、またはカスタムソート後に同じ順序で複数のレコードが存在する場合、デフォルトのソートが追加で適用されます。デフォルトのソートは、データが最終的に厳密な順序を持つことを保証するために、作成時間または最終更新時間のみを使用できます。",
