  "请输入外部公开页面的完整URL地址。注意：无法获取需要登录的页面，且外部页面可能无法完整捕捉或可能出错，建议使用前进行简单的测试。": "外部公開ページの完全なURLアドレスを入力してください。注意：ログインが必要なページにはアクセスできず、外部ページは完全にキャプチャされないか、エラーが発生する可能性があります。使用する前に簡単なテストを行うことをお勧めします。",
  "该账号已停用": "このアカウントは無効になっています",
