  "组件只支持 function 写法，你需要在编辑器里实现这样一个函数。只支持写一个函数，所有逻辑在函数内实现。不可以使用 import，所有逻辑都需要原生实现。React 下的所有属性都已经暴露到组件内，你可以直接使用。": "コンポーネントは関数の記述のみをサポートしています。エディタ内でこのような関数を実装する必要があります。関数は1つのみサポートされ、すべてのロジックはその関数内で実装される必要があります。importの使用はできず、すべてのロジックはネイティブで実装する必要があります。Reactのすべてのプロパティはコンポーネント内で公開されており、直接使用することができます。",
