  "[返回类型]：指定周数的计算方式。默认值为 1，表示一周从周日开始，周日为一周的第一天": "[返却タイプ]：週数の計算方法を指定します。デフォルト値は1で、週は日曜日から始まり、日曜日が週の最初の日となります。",
  "委托内容": "委託内容",
  "为完整显示历史引用关系，需通过初始化对全组织工作流节点进行扫描，以获取所有工作流对字段及表的引用情况。": "履歴参照関係を完全に表示するには、初期化して全組織のワークフローノードをスキャンし、すべてのワークフローにおけるフィールドおよびワークシートの参照状況を取得する必要があります。",
  "本次测试消耗 %0 tokens， 计费 %1 $": "今回のテストは %0 トークンを消費し、料金は %1 $ です",
  "当可以保证配置的自定义排序严格有序，或已经为自定义排序创建了索引时，可以勾选不追加默认排序。注意：如果不满足以上条件就取消了追加的默认排序，可能会因为同顺序下有多条记录，而导致翻页时数据缺少或重复。": "カスタムソートの設定が厳密に順序付けられていることが保証されている場合、またはカスタムソートのためにインデックスがすでに作成されている場合は、デフォルトのソートを追加しないようにチェックすることができます。注意：以上の条件が満たされていない場合にデフォルトのソートの追加をキャンセルすると、同じ順序に複数のレコードが存在するため、ページネーション時にデータが欠落したり重複したりする可能性があります。",
  "API安全": "APIセキュリティ",
  "支付宝官网": "アリペイ公式サイト",
  "您已升级至更高的版本": "より高いバージョンにアップグレードしました",
  "3.离线录入时，表单的业务规则、字段验证和权限控制都不生效。数据暂存本地，网络恢复后需手动提交，确保数据结构完整性。": "3. オフラインで入力する際、フォームのビジネスルール、フィールド検証、権限制御は無効になります。データはローカルに一時保存され、ネットワークが回復した後に手動で送信する必要があります。データ構造の完全性を確保してください。",
  "微信支付商户号": "WeChatペイメント商業番号",
