  "商户APIv2密钥": "マーチャントAPI v2キー",
  "若想恢复组织，请到个人账户 - 我的组织 找到已关闭的组织列表进行恢复": "組織を復元したい場合は、個人アカウント - マイ組織に移動し、閉じた組織のリストを見つけて復元してください。",
