  "上传的图标可用于应用配置时的图标选择，建议使用 SVG 格式的单色图标": "アップロードされたアイコンは、アプリケーション設定時のアイコン選択に使用できます。SVG形式の単色アイコンを使用することをお勧めします。",
  "天数：一个正数表示向后推算天数，一个负数表示向前推算天数": "日数：正の数は未来の日数を示し、負の数は過去の日数を示します。",
  "关闭超过90天的组织，所有应用将自动进入回收站，进入回收站60天后，所有应用将被彻底物理删除": "90日以上活動していない組織を閉じると、すべてのアプリケーションが自動的にゴミ箱に移動されます。ゴミ箱に60日間保存された後、すべてのアプリケーションは完全に削除されます。",
  "示例：=ASIN(0.84114709848079) 返回近似值 0.999400825621613，即正弦值为 0.8411470984807897 的角度的弧度（约为 57.3 度）。": "例：=ASIN(0.84114709848079)は、近似値0.999400825621613を返します。これは、正弦値が0.8411470984807897の角度のラジアン（約57.3度）です。",
