  "使用微信商户号开通；费率参考微信支付官方规则": "WeChatマーチャント番号を使用してアクティブ化；料金はWeChat Pay公式ルールを参照",
  "生成一个从本周周一开始的7天的日期选择器，日期以胶囊的形式展示，用户选中日期后保存。如果载入时有值，则显示为值所在的那一周的7天，并默认选中值。当组件参数 env 中的 isDisabled 为 true 时，禁用日期选择器。": "今週の月曜日から始まる7日間のデートピッカーを生成し、日付はカプセル形式で表示されます。ユーザーが日付を選択した後に保存します。読み込み時に値がある場合は、その値の週の7日間を表示し、自動的に値を選択します。コンポーネントのenvパラメータのisDisabledがtrueの場合、日付選択器を無効にします。",
  "同时开启公开表单、支付金额字段选择金额/数值，开启设置交易有效期才能开启，开启后支付成功才能提交表单数据，否则表单数据不提交": "同時に公開フォームを開き、支払い金額フィールドで金額/値を選択できるようにします。取引の有効期限を設定して初めて有効にすることができます。有効にした後、支払いが成功した場合にのみフォームデータを送信でき、それ以外の場合はフォームデータは送信されません。",
