  "展示工作流对当前字段的关键引用，主要包括筛选条件、动态值设置、人员配置等可能影响流程执行或数据准确性的引用": "現在のフィールドに関連する主要なワークフロー参照を表示します。これには、フィルター、動的値、ワークフロー実行やデータ精度に影響を与える可能性のある担当者設定などが含まれます。",
