  " 在微信商户后台的“产品中心”—“我的产品”页面中开通JSAPI支付和Native支付，如果其中一个支付方式未开通，在配置微信支付时会报“该商户号未开通公众号支付”的错误提示。": "WeChatのマーチャントバックエンドの「製品センター」-「私の製品」ページでJSAPI決済とネイティブ決済を開通します。もしどちらかの決済方式が開通していない場合、WeChat決済を設定すると「このマーチャント番号は公式アカウント決済を開通していません」というエラーメッセージが表示されます。",
