  "新版本重构了工作表的架构。如遇问题，可点击按钮返回旧版本，继续使用熟悉的功能和界面。": "新しいバージョンではワークシートのアーキテクチャが再構築されました。問題が発生した場合は、ボタンをクリックして旧バージョンに戻り、なじみのある機能とインターフェースを引き続き使用できます。",
