  "1、启用应用内的支付功能必须要先在组织后台申请商户号并完成签约。商户签约是由第三方支付公司提供。": "1、アプリ内の支払い機能を有効にするには、まず組織のバックエンドでマーチャント番号を申請し、契約を完了する必要があります。マーチャントの契約は第三者の決済会社が提供します。",
  "这个组件功能是去到名称的值，放大以红色显示出来。组件接收 `formData` 属性，formData 是记录的字段数据，你需要先在编辑器右上角把字段添加到引用并设置别名。这时你可以通过 `formData[env.别名]`来获取到对应的字段。": "このコンポーネントの機能は、名前の値を取得し、赤色で拡大表示することです。このコンポーネントは `formData` 属性を受け取り、formData はレコードのフィールドデータです。最初にエディタの右上隅でフィールドを参照に追加し、エイリアスを設定する必要があります。この時、`formData[env.エイリアス]`を通じて対応するフィールドを取得できます。",
