  "群成员（%0人）": "グループメンバー（%0人）",
  "返回数值的反正弦值": "数値の逆正弦を返す",
  "生成一个仓库的平面示意图，在平面图上从左至右排列可以点击选择的仓库，每个仓库的左上角有一个小的出入口。仓库的数据来自本字段 options 数组下的内容，value 是名称，color 是它的颜色。用户可以点击选中多个仓库，选中后以 JSON 数组格式字符串保存选中的仓库的 key值。如果载入时有值，将值回显到仓库上显示。当组件参数 env 中的 isDisabled 为 true 时，禁止选择仓库，只能查看。": "倉庫の平面図を生成します。図の左から右にかけて、クリック選択可能な倉庫が配置されており、各倉庫の左上隅には小さな入り口があります。倉庫のデータは、このフィールドの options 配列の内容から取得され、value が名称、color がその色です。ユーザーは複数の倉庫をクリックして選択することができ、選択後、選ばれた倉庫のキー値が JSON 配列形式の文字列として保存されます。読み込み時に値がある場合、値が倉庫に表示されます。コンポーネントパラメータ env の isDisabled が true の場合、倉庫の選択は無効となり、表示のみが可能です。",
  "4、密钥、证书等字段信息采用动态加密存储，保存后掩码显示，保障信息安全": "4、キー、証明書などのフィールド情報は動的に暗号化されて保存され、保存後はマスク表示されるため、情報の安全が保障されます。",
