  "%0 于%1天前关闭": "%0は%1日前に閉じられました",
  "生成公钥、私钥、CSR：支付宝开放平台开发助手提供了一键生成密钥功能，便于开发者生成一对 RSA密钥（应用公钥、应用私钥）以及公钥证书申请 CSR 文件（在线申请应用公钥证书需要）。请点击查看详细步骤介绍，并按照步骤一一设置完成，完成后会获得如下图所示的公钥、私钥、CSR，请保存方便后续使用。": "公開鍵、秘密鍵、CSRを生成する：Alipayオープンプラットフォーム開発アシスタントは、開発者が1対のRSA鍵（アプリケーション公開鍵、アプリケーション秘密鍵）と公開鍵証明書要求CSRファイル（アプリケーション公開鍵証明書をオンラインで申請するために必要）を生成するためのワンクリック鍵生成機能を提供しています。詳細な手順紹介をご覧いただき、手順に従って設定を完了してください。完了後、下の図に示す公開鍵、秘密鍵、CSRを取得しますので、今後の利用のために保存してください。",
