  "平台不收取任何微信支付手续费，从微信商户号后台提现到银行卡免费，但提现前需要结算，会按单笔订单收取对应的结算手续费，微信支付商户后台提现介绍点击查看，具体费率 点击查看。": "プラットフォームはWeChat Payの手数料を一切徴収せず、WeChatのマーチャントアカウントから銀行口座への引き出しは無料ですが、引き出しの前に精算が必要で、各取引ごとに対応する精算手数料が課金されます。WeChat Payのマーチャントバックエンドの引き出しの紹介をクリックして確認し、具体的な料金についてはクリックして確認してください。",
  "上传apiclient_cert.p12文件，将其转成base64的文本内容，将文本内容复制粘贴到商户API证书字段内。": "apiclient_cert.p12ファイルをアップロードし、それをbase64テキストコンテンツに変換して、そのテキストコンテンツをマーチャントAPI証明書フィールドにコピー＆ペーストします。",
