  "按下方步骤获取上面所需信息。": "下の手順に従って、上に必要な情報を取得してください。",
  "在表格右侧显示操作列，可以对每行记录进行快速操作": "テーブルの右側に操作列を表示し、各レコードに対して迅速に操作を行うことができます。",
  "签名内容长度为2-20个字；由中英文组成，不能纯英文；签名内容必须能辨别所属公司名称或品牌名称；不符合规范的签名平台会清空需重新输入，同时运营商也会拦截。": "署名内容の長さは2〜20文字である必要があります。中国語と英語の両方で構成されている必要があり、純粋な英語は使用できません。署名内容は所属会社名またはブランド名を識別できる必要があります。規定に合わない署名はプラットフォームによってクリアされ、再入力が必要になります。また、運営者もそれを阻止します。",
  "出于安全考虑，原始密钥信息不能直接编辑，点击上方按钮进行替换更新": "セキュリティ上の理由から、元のキー情報は直接編集できません。上部のボタンをクリックして置き換えと更新を行ってください。",
