  "指在审批流程中当人员设置为直属上级、上级部门负责人时。如果当前人员没有直属上级，则由本人自己处理；如果当前人员、部门没有上级部门，则由本部门负责人处理。未勾选时，则按照为空处理。": "承認の設定を行う際に、表示、編集、必須フィールドを確認できます。要約として設定されたフィールドは、プロセスの保留タスクリストやメール通知に直接表示され、承認者は詳細を開かずに迅速に承認を完了できます。",
