  "用量不足时自动消耗余额增补，10元/1,000次": "使用量が不足する際に自動的に残高を補充、10元/1,000回",
  "选择关联表的一个字段作为映射的匹配字段，支持的字段类型包括：文本框、电话号码、邮件地址、证件、文本拼接、自动编号、记录ID": "関連するテーブルから、マッピングのマッチングフィールドとしてフィールドを選択します。サポートされるフィールドタイプは、テキストボックス、電話番号、電子メールアドレス、ID、テキストスプライス、オートナンバー、レコードIDです。",
