  "导入失败，组织下应用数量已达上限": "インポートに失敗しました。組織のアプリ上限に達しています。",
  "发送服务号消息是指向已关注服务号的微信用户发送模版消息。发送对象支持使用人员字段（通过微信授权注册的外部门户用户）或文本字段（存储微信服务号openid）。使用微信服务号模板消息需要组织后台绑定已认证的企业服务号，并在微信服务号后台开通“模板消息”功能。": "サービスアカウントメッセージを送信するとは、サービスアカウントをフォローしているWeChatユーザーにテンプレートメッセージを送信することを指します。送信対象は、ユーザー分野（WeChat認証登録された外部ポータルユーザー）またはテキストフィールド（WeChatサービスアカウントのopenidを保存）の使用をサポートしています。WeChatサービスアカウントテンプレートメッセージを使用するには、組織のバックエンドで認証された企業サービスアカウントをバインドし、WeChatサービスアカウントのバックエンドで「テンプレートメッセージ」機能を有効にする必要があります。",
