  "在进行工作表和工作流的所有下级部门检索时，若所有下级部门总数超过2000（含），系统将默认仅获取当前部门的“一级子部门”所有部门。": "ワークシートおよびワークフローですべての下位部門を検索する場合、すべての下位部門の合計数が2,000（含む）を超えると、システムは現在の部門の「第一レベルの下位部門」であるすべての部門のみを取得するようにデフォルト設定されます。",
  "当前应用已过期，如要继续使用，请立即续订": "現在のアプリケーションは期限切れです。引き続き使用するには、今すぐ更新してください。",
