  "未勾选时，对于错误的数据仅跳过错误字段，其他字段仍然导入。勾选后将跳过整行数据。": "チェックを外すと、不正なデータの場合、不正なフィールドのみがスキップされ、他のフィールドはそのままインポートされます。チェックした場合は、データの行全体がスキップされます。",
  "签名规范：签名内容长度为2-12个字；由中英文组成，不能纯英文；签名内容必须能辨别所属公司名称或品牌名称；不符合规范的签名平台会清空需重新输入，同时运营商也会拦截。": "サインの規則：サインの内容は2〜12文字の長さでなければならず、中英の組み合わせで構成されている必要があります。純粋な英語ではいけません。サインの内容は関連する会社名またはブランド名を判断できるものでなければなりません。規則に従わないサインはプラットフォームによってクリアされ、再入力が必要です。また、運営者によってもブロックされます。",
  "向工作表新增一条或多条记录": "ワークシートに1件以上のレコードを追加",
  "将选项等复杂字段作为文本使用时请使用STRING函数，比如": "オプションなど、複雑なフィールドをテキストとして使用する場合はSTRING関数を使用してください。例：",
