  "您获取的多条数据可供本流程的数据处理节点或子流程节点使用。被数据处理节点（新增、更新、删除）使用，最多支持%0条。被子流程节点使用，最多支持%1条。": "取得したデータの複数の項目は、このプロセスのデータ処理ノードまたはサブプロセスノードで使用できます。データ処理ノードによって使用され (追加、更新、削除)、%0 項目までサポートされます。サブプロセス・ノードによって使用され、%1 項目までサポートされます。",
