  "第2步": "ステップ2",
  "未勾选时，用户在关联列表中可以查看所有关联数据。勾选后，按照用户对关联的工作表/视图的权限查看，隐藏无权限的数据或字段": "チェックされていない場合、ユーザーは関連するリストですべての関連データを見ることができます。チェックが入っている場合、関連するシート/ビューのユーザーの権限に応じて、権限のないデータやフィールドは非表示になります",
