  "计算式：'+'或'-'代表添加或减去；时间段的单位，'Y'代表年、'M'代表月、'd'代表天、'h'代表小时、'm'代表分钟；也可以添加或减去一个时间字段": "計算式：「+」または「-」で加算または減算、期間の単位：「Y」で年、「M」で月、「d」で日、「h」で時間、「m」で分、時間フィールドも加算または減算可能",
