  "应用于所有记录中的按钮，无法从当前视图中删除": "すべてのレコードに適用されたボタンは、現在のビューから削除することはできません",
  "未勾选时，用户可查看、编辑所有明细。勾选后，按照用户在实体工作表中配置的权限生效，包含对明细的新增、查看，编辑，删除；以及对字段的可见、编辑权限": "チェックしない場合、ユーザーはすべての詳細を表示および編集できます。チェックすると、エンティティワークシートでユーザーが設定した権限が有効になり、詳細の追加、表示、編集、削除に加え、フィールドの可視性および編集権限が含まれます。",
  "多表连接后左右两个数据表将按设置的条件进行匹配，并将符合条件的记录进行合并。": "複数テーブル結合後、設定条件で一致するレコードをマッチングし統合します",
