  "发送服务号消息是指向已关注公众号的微信用户发送模版消息。发送对象支持使用人员字段（通过微信授权注册的外部门户用户）或文本字段（存储微信公众号openid）。使用微信公众号模板消息需要组织后台绑定已认证的企业服务号，并在微信公众号后台开通“模板消息”功能。": "サービスアカウントメッセージの送信は、フォローしている公式アカウントのWeChatユーザーにテンプレートメッセージを送信することを指します。送信対象は、従業員フィールド（WeChatの認証を通じて登録された外部ポータルユーザー）またはテキストフィールド（公式アカウントのopenidを保存）を使用することをサポートしています。公式アカウントのテンプレートメッセージを使用するには、組織のバックエンドが認証された企業サービスアカウントにバインドされ、公式アカウントのバックエンドで「テンプレートメッセージ」機能を有効にする必要があります。",
