  "执行到本节点时保存该记录更新前的数据，供流程中的其他节点使用": "このノードで更新前データを保存し、他ノードで利用できます。",
  "设置填写内容%02060": "入力内容を設定する",
  "设置筛选条件，获得满足条件的数据。如果未添加筛选条件，则只从当前组织的所有组织角色中获得第一个（最新创建）角色的相关信息": "フィルタリング条件を設定して、条件を満たすデータを取得します。フィルタリング条件を追加しない場合は、現在の組織のすべての組織ロールから最初の（最新作成）ロールの関連情報のみが取得されます。",
  "获取记录数量上限": "レコード件数の上限を取得",
  "没有搜索到\"": "検索結果が見つかりませんでした\\\"",
  "1.什么是“企业微信用户账号”": "1. 「企業微信ユーザーアカウント」とは何ですか？",
  "短信%0/条，自动从企业账务中心扣费。70字计一条短信，超过70字以67字每条计费。每个标点、空格、英文字母都算一个字。短信实际发送可能有10-20分钟的延时。": "SMS %0/テキストは企業会計センターから自動的に差し引かれます。 70 文字は 1 つのテキスト メッセージとしてカウントされ、70 文字を超えるメッセージは 67 文字として課金されます。句読点、スペース、英字はそれぞれ 1 単語としてカウントされます。実際のテキスト メッセージの送信には 10 ～ 20 分の遅延が発生する場合があります。",
  "设置筛选条件，获得满足条件的数据。如果未添加筛选条件，则只从字段中获得第一名人员的相关信息": "フィルター条件を設定すると、条件を満たしたデータを取得することができます。フィルター条件を付けない場合は、フィールドから1人目の情報のみを取得する",
  "记录创建次数": "作成回数記録",
  "没有可导入Sheet": "インポート可能なワークシートがありません",
  "从工作表中通过筛选条件和排序规则直接删除符合条件的唯一数据": "フィルタリング条件とソートルールにより、条件を満たすユニークなデータをワークシートから直接削除します。",
  "被以下工作流触发": "以下のワークフローによってトリガーされました",
  "3. 在开放平台，选择“企业内部应用”下的“轻应用”，创建轻应用": "3. オープンプラットフォームで“企業内部アプリケーション”の“ライトアプリケーション”を選択し、ライトアプリケーションを作成します。",
  "参数满足下面条件时退出循环，请在循环中更新参数值以触发条件": "パラメータが以下の条件を満たしたときにループを終了します。条件をトリガーするためにループ内でパラメータ値を更新してください。",
