  "通过工作流发送邮件时，链接可以按照设置的链接名称显示。如：在邮件中将链接显示为【点击查看记录】": "ワークフローを通じてメールを送信する際、リンクは設定されたリンク名で表示できます。例えば：メール内でリンクを【レコードを表示】として表示する",
