  "回到组织管理后台的钉钉对接部分，开启第四步的功能开关": "組織管理バックエンドのDingTalkインテグレーション部分に戻り、ステップ4の機能スイッチをオンにします。",
  "图片标题": "画像キャプション",
  "按照所选视图配置的显示字段发送，如果操作者被分发了此视图，可以直接按权限编辑记录、执行自定义动作": "選択したビューに基づいて構成された表示フィールドを送信します。オペレーターがこのビューに割り当てられている場合、権限に応じてレコードを直接編集し、カスタムアクションを実行できます。",
