  "获取多名人员的相关信息，包含个人信息（姓名、性别、生日、手机、邮箱）和组织信息（部门、职位、工号、上下级（可选）），供流程中的其他节点使用。": "複数の人員に関する情報を取得します。個人情報（名前、性別、生年月日、電話番号、メール）と組織情報（部門、職位、社員場合、上下関係（任意））を含み、プロセス内の他のノードで使用します。",
  "这些是您短信模板中使用到的动态值，请给出范例数据用于人工审核时验证您的短信类型": "これらは、SMSテンプレートで使用される動的値です。人工審査であなたのSMSタイプを検証するためのサンプルデータを提供してください。",
