  "获取一名人员的相关信息，包含个人信息（姓名、性别、生日、手机、邮箱）和组织信息（部门、职位、工号、上下级（可选）），供流程中的其他节点使用。": "個人情報（氏名、性別、誕生日、携帯電話、電子メール）および組織情報（部署、役職、社員場合、部下（任意））を含む個人に関する情報を取得し、プロセスの他の時点で使用すること",
  "勾选后，将会生成一个记录Body全文的文本格式参数": "チェックすると、Bodyのフルテキストを記録するためのテキストフォーマットパラメータが生成されます。",
  "公开表单仅统计非平台登录用户上传的附件": "公開フォームは、プラットフォームにログインしていないユーザーがアップロードした添付ファイルのみを集計します",
