  "创建数据源时，检查数据库服务器的连通性、账户密码等正确性、数据库是否可用、以及检查是否可以作为源或者目的地。只有数据源通过全部测试才能够正常使用数据源。": "データソースを作成する際には、データベースサーバーの接続性、アカウントパスワード等の正しさ、データベースの可用性を確認し、ソースまたはデスティネーションとして使用可能かどうかをチェックします。すべてのテストに合格して初めて、データソースを正しく使用することができます。",
  "全连接": "全接続",
