  "启用后，可以为每个选项赋分值。赋值后的选项字段可以公式运算或作为数值字段默认值使用。字段值取所有选择项的分值求和，支持输入正负值。": "有効にすると、各オプションにスコアを割り当てることができます。スコアを付けたオプションフィールドは、数式計算に使用したり、数値フィールドのデフォルト値として使用したりできます。フィールドの値は、すべての選択項目のスコアの合計であり、正の値と負の値の両方を入力できます。",
  "你可以把 MariaDB 数据库的数据通过系统实时同步到工作表或者其它数据目的地。": "MariaDBデータベースからのデータを、システムを通じてリアルタイムにワークシートやその他のデータ宛先に同期できます。",
