  "告诉AI模型在生成响应时应该如何行为以及需要参考的任何上下文。你可以描述助手的个性，告诉它应该回答什么和不应该回答什么，并告诉它如何格式化响应。系统消息将按所消耗token数进行计费。": "AI モデルに、応答と参照する必要があるコンテキストを生成するときにどのように動作すべきかを伝えます。アシスタントの性格を説明し、何を答えるべきか、何を答えるべきではないかを指示し、応答の形式を指示することができます。システム メッセージは、消費されたトークンの数に基づいて課金されます。",
