  "设置后，在扣款时若组织账户余额低于预警值则会发送预警给通知人（每天仅发送 1 次预警，若重置预警值则会再次发送）": "設定後、引き落とし時に組織アカウント残高が警告値を下回った場合、通知者に警告が送信されます（警告は1日1件のみ送信され、警告値がリセットされると再度送信されます）。",
