  "用于在邮件节点中插入动态值时指代当前节点，比使用节点ID更有辨识度。节点别名仅允许使用字母（不区分大小写）、数字和下划线组合，且必须以字母开头，不可重复。": "メールノード内で動的値を挿入する際に、現在のノードを指すために使用され、ノードIDを使用するよりも識別しやすいです。ノードエイリアスは、文字（大文字と小文字を区別しない）、数字、アンダースコアの組み合わせのみが許可されており、必ず文字で始める必要があります。重複することはできません。",
  "指定一个日期字段，将字段的日期作为时间表来触发流程。如：指定工作表中的员工生日或客户注册日期来发送短信通知": "日付フィールドを指定し、そのフィールドの日付をタイムテーブルとしてプロセスをトリガーします。例：ワークシート内の従業員の誕生日または顧客の登録日を指定してSMS通知を送信します。",
