  "设置输入参数": "入力パラメータの設定",
  "请输入指定错误码，如：400,401(多个状态码用英文逗号隔开)": "指定されたエラーコードを入力してください。例: 400,401（複数のステータスコードはコンマで区切ってください）",
  "在审批节点下添加分支有两种选择：": "承認ノードの下に分岐を追加するには2つのオプションがあります：",
  "字数": "文字数",
  "开启后无论子表中是否存在记录，都会显示固定数量的行数。当子表没有记录时，将显示空白行。": "オンにすると、サブテーブルにレコードが存在するかどうかに関係なく、固定数の行が表示される。サブテーブルにレコードがない場合、空白の行が表示される。",
  "从工作表获取多条记录": "ワークシートから複数のレコードを取得する",
  "查询到的每行记录添加为一行子表明细。请选择需要写入的字段。": "クエリの各行は、サブ詳細の行として追加されます。書き込むフィールドを選択してください。",
  "绝对值": "絶対値",
