  "输出参数配置有误": "出力パラメータの設定が誤っています",
  "汇总结果": "集計結果",
  "传入 JSON 对象数组格式的会话历史，将有助于AI理解上下文并进行连续对话。会话历史将按所消耗 token 数进行计费。": "会話履歴を JSON オブジェクト配列形式で渡すと、AI がコンテキストを理解し、継続的な会話を行うのに役立ちます。セッション履歴は、消費されたトークンの数に基づいて課金されます。",
  "预置常用的意见作为模板，帮助审批人快捷填写": "よく使われるコメントをテンプレートとしてセットし、承認者が迅速に記入できるようにします。",
  "右侧（否决分支）": "右側（否決ブランチ）",
  "取消勾选后，则编号不允许超出指定的位数，到达最大后将从0开始重新计数。如果位数设置不足会导致编号重复": "チェックを外すと、番号は指定された桁数を超えることはできません。最大に達すると、再び0からカウントが始まります。桁数の設定が不足していると、番号が重複する可能性があります。",
  "发送指定数据对象": "指定されたデータオブジェクトを送信する",
