  "主题：": "件名",
  "邀请多名用户": "複数のユーザーを招待する",
  "从记录链接获取": "レコードリンクから取得",
  "创建一个系统内日程。可同时生成一个ICS文件在其他节点中使用": "システム内にスケジュールを作成します。他のノードで使用するために同時にICSファイルが生成されます。",
  "配置 Access Token 刷新条件": "アクセストークンのリフレッシュ条件を設定する",
  "唯一分支": "ユニークブランチ",
  "未配置 PDF 转换服务": "PDF変換サービスが設定されていません",
  "获取关联记录": "関連レコードの取得",
  "的直接部门负责人": "直接の部署責任者",
  "从工作表中筛选符合条件的数据并进行汇总计算，如：记录数量、求和、平均、最大、最小等。注意：当汇总他表字段或者数据频繁变更时可能有一定延时": "ワークシートから条件に合うデータを抽出し、件数、合計、平均、最大、最小などを集計します。※他テーブルのフィールドや頻繁に変化するデータを集計する際は遅延が発生する場合があります。",
  "对查找到的数据进行分支处理。未查找到数据时，流程中止": "このブランチはデータを処理します。データが見つからない場合は終了します。",
  "请填写限制结尾显示的字数": "表示される文字数を制限してください",
  "向上19级": "上に19レベル",
  "审批设置": "承認設定",
  "数据源：": "データソース：",
  "向上7级": "7レベル上",
  "校准刷新符合筛选条件的工作表记录的计算结果、选项排序和分值、他表字段和汇总结果，此节点为异步排队执行，一次最多刷新10万行记录。每次校准必须间隔120分钟以上，否则将跳过节点": "キャリブレーションにより、フィルタリングされたレコードの計算、並べ替え、スコア、外部フィールド、サマリーが更新されます。これは非同期で実行され、最大10万行を処理します。実行間隔は120分です。そうでない場合、ノードはスキップされます。",
  "请输入补充信息": "追加情報を入力してください",
  "通道：${routerList[v]}": "チャネル：${routerList[v]}",
  "这是一个兼容保留的历史配置，现在此字段类型已不再支持此设置。如果你不需要此功能可以取消勾选，避免性能浪费。": "これは互換性を保つための履歴設定であり、現在このフィールドタイプはこの設定をサポートしていません。この機能が必要ない場合は、パフォーマンスの無駄を避けるためにチェックを外すことができます。",
  "获取多条人员信息": "複数の人員情報を取得する",
  "选中后，不允许用户填写和已有字段值重复的数据，但对工作流或API写入、批量导入等操作不做限制。": "選択後、ユーザーは既存のフィールド値と重複するデータを入力できませんが、ワークフローやAPI書き込み、バルクインポートなどの操作には制限がありません。",
