  "正在查看历史执行详情（${dayStr} ${time}），本月新增、本月排队指截止到 ${dayStr} ${time} 的值": "履歴実行の詳細を表示中です（${dayStr} ${time}）、今月の新規追加、今月のキュー値は ${dayStr} ${time} の値です。",
