  "备用：限流通道。用于临时处理主要通道中发生堆积的流程执行。或处理响应时效要求低的流程，使用此通道更稳定。": "バックアップ：スロットルチャネル。主チャネル内で発生したプロセスの実行が蓄積された場合に、一時的に処理するために使用します。また、応答時間の要件が低いプロセスを処理するためにも、このチャネルを使用するとより安定します。",
  "您获取的多条数据可供本流程的数据处理节点或子流程节点使用。被数据处理节点（新增、更新、删除）使用，最多支持100条。被子流程节点使用，最多支持1万条。": "取得した複数のデータは、本プロセスのデータ処理ノードまたはサブプロセスノードで使用できます。データ処理ノード（追加、更新、削除）によって使用される最大件数は100件です。サブプロセスノードによって使用される最大件数は1万件です。",
