  "赋值": "値の割り当て",
  "强制中止当前流程，后续所有节点不再执行。在封装业务流程中，输出参数中所有引用本节点之后的值将输出空值。在配置了开启了平台 API 的封装业务流程或配置了自定义响应的Webhook流程中，响应值中所有引用本节点之后的值将输出空值。": "現在のプロセスを強制的に中止します。以降のすべてのノードは実行されません。ビジネスプロセスのカプセル化では、出力パラメータ内のこのノード以降のすべての参照値は空値として出力されます。プラットフォームAPIが有効になっているカプセル化されたビジネスプロセスや、カスタムレスポンスのWebhookプロセスでは、レスポンス内のこのノード以降のすべての参照値も空値として出力されます。",
