  "允许审批人批量、快速处理审批任务（在移动端可以直接点击待审批列表上的按钮进行审批）。在批量处理审批时将忽略表单中的必填字段。": "承認者が承認タスクを迅速に一括で処理できるようにします（モバイル端末では、保留中の承認リストのボタンを直接クリックして承認できます）。一括処理の際、フォーム内の必須フィールドは無視されます。",
