  "如果分解后的任务比较复杂、需要分别指派负责人，或需要在每条任务中分别记录跟进情况的，建议使用子任务。其他情况下，建议使用检查清单来做关键结果追踪，支持将重要检查项一键转为任务": "分解されたタスクが複雑で、各タスクの責任者を個別に指名する必要がある場合や、各タスクのフォローアップ状況を個別に記録する必要がある場合は、サブタスクを使用することをお勧めします。その他の場合は、重要なチェック項目をタスクに1クリックで変換できるチェックリストを使用して、重要な結果の追跡を行うことをお勧めします。",
