  "截止到目前为止任务负责人负责的任务逾期时间统计，包含进行中和已完成的逾期时间，向下取整。如：3个进行中任务逾期时间累计为15小时，则显示总逾期0天，若累计为26小时，则显示总逾期1天，以此类推": "現時点までのタスク責任者の合計時間を統計する（進行中および完了した期限切れの時間を含む）、外統計は切り捨てられます。たとえば、3つのタスクが合計15時間遅れている場合、合計0日の遅れが表示され、26時間累積された場合、合計1日の遅れが表示されます",
