  "建立唯一索引后，字段的值不允许重复。如果字段为非必填，则整个工作表只能有一条为空的数据，以保证数据的唯一性": "一意のインデックスを作成すると、フィールドの値は重複してはいけません。フィールドが必須でない場合、ワークシート全体に空のデータが1つだけ存在できるようにして、データの一意性を保証します。",
