  "检测到您输入了 %0 行内容,可以为您创建 %0 条记录。您也可以只创建一条记录": "%0 行の内容が入力されたことを検出しました。%0 件のレコードを作成できます。また、一件のレコードだけを作成することも可能です。",
  "并非如此。索引只会加速检索，而在新增、更新、删除记录时系统会花费更多的时间用于更新索引，过多的索引会很明显的降低这些操作的速度，甚至影响到查询的速度。": "そうではありません。インデックスは検索を加速するだけであり、レコードの追加、更新、削除を行う際には、システムはインデックスの更新により多くの時間を費やします。過剰なインデックスは、これらの操作の速度を著しく低下させ、さらにはクエリの速度にも影響を与える可能性があります。",
