  "如果一些字段总是需要一起参与检索，它们组合起来之后的重复率更低，例如「First Name」和「Last Name」，那么你可以同时选择这两个字段创建一个复合索引，比为这两个字段分别创建索引效果更好。": "いくつかのフィールドが常に一緒に検索される必要がある場合、それらを組み合わせることで重複率が低くなります。例えば「First Name」と「Last Name」です。これらの2つのフィールドを同時に選択して複合インデックスを作成することで、各フィールドのために別々のインデックスを作成するよりも効果的です。",
