  "选择一个代码块、发送API请求、JSON解析或调用已集成API节点，把它的返回数据对象立即返回给请求方；请控制请求频率在500次/小时以内，流程执行时间30s以内，私有部署不限": "コードブロックを選択し、APIリクエストを送信し、JSONを解析するか、統合されたAPIノードを呼び出して、その返されたデータオブジェクトをリクエスト元に即座に返します；リクエストの頻度は1時間あたり500回以内に制御してください。プロセスの実行時間は30秒以内で、プライベートデプロイに制限はありません。",
