  "设为隐藏后，普通用户在导航中将看不到此应用项入口，仅系统角色在导航中可见（包含管理员、开发者），应用项权限依然遵循角色权限原则。此配置通常用于不需要用户直接访问，仅作为配置用途的应用项，如：关联的明细表、参数表等。": "非表示に設定すると、一般ユーザーはナビゲーションにこのアプリケーション項目のエントリを見ることができなくなり、システムロール（管理者や開発者を含む）だけがナビゲーションに表示されます。アプリケーション項目の権限は引き続きロール権限の原則に従います。この設定は通常、ユーザーが直接アクセスする必要がなく、設定目的のアプリケーション項目に使用されます。例：関連する明細表、パラメーター表など。",
