  "每张工作表只能创建一个「文本索引」或者「文本字段全文索引」；创建「文本索引」时，不能包含「选项字段」；每个索引只能包含一个「选项字段」": "各ワークシートには「テキストインデックス」または「テキストフィールドの全文インデックス」を1つだけ作成できます。「テキストインデックス」を作成する際には「オプションフィールド」を含めることはできません; 各インデックスには1つの「オプションフィールド」だけを含めることができます。",
