  "编码方式：code128，仅支持数字、字母、符号，最大包含30个字符": "エンコーディング方式：code128、数字、アルファベット、記号のみをサポート、最大30文字を含む",
  "您确认复制这%0条记录吗？": "%0件のレコードをコピーしますか？",
  "此时对方请求时必须附带参数callbackURL，我方流程运行结束后会向此URL传递输出参数": "その時、相手のリクエストには必ずcallbackURLパラメーターを含める必要があります。私たちのプロセスが終了した後、このURLに出力パラメーターを渡します。",
