  "为你的应用添加用户。你可以创建角色来管理用户权限，一条数据，谁能查看，谁能修改，谁能删除，都能自由设定。": "ロールを作成して権限を管理し、アプリケーションにユーザーを追加できます。各ロールごとに、レコードの閲覧・編集・削除権限を設定できます。",
