  "当前节点未进行操作的成员将设为提交": "現在のノードで操作していないメンバーは、提出として設定されます",
  "立即导出": "エクスポート",
  "刷新选项排序和分值": "オプションの並べ替えと値を更新",
  "插件设置": "プラグイン設定",
  "通知节点设置": "通知ノード設定",
  "是的，我们会根据公有云平台每天的访问日志，自动学习和智能分析被频繁使用的查询语句，并自动创建合适的索引。所以，请不要随意修改和删除不是由你自己创建的索引。私有部署环境暂不支持自动创建索引。": "はい、私たちは公共クラウドプラットフォームの日次アクセスログに基づいて、頻繁に使用されるクエリ文を自動学習し、インテリジェントに分析し、適切なインデックスを自動的に作成します。したがって、自分で作成していないインデックスを勝手に変更したり削除したりしないでください。プライベートデプロイ環境は、自動インデックス作成をサポートしていません。",
  "插件 “%0” 存在错误！": "プラグイン「%0」にエラーがあります!",
  "你可以根据业务数据自定义工作表字段，并建立数据关联。": "ワークシートの項目をカスタマイズし、データの関連付けを設定できます。",
  "已选择%0条草稿": "%0 件の下書きが選択されました",
  "添加视图": "ビューを追加",
  "为工作表建立索引，就像是为一本字典建立一个可以用拼音检索的目录。创建适合的索引可以非常有效的加快特定查询条件下的记录检索速度。在创建索引之前，你需要了解创建索引的一些基本原则。": "ワークシートのインデックス作成は、辞書の目次作成に似ています。適切なインデックスは検索速度を向上させます。インデックス作成前に、基本原則を理解する必要があります。",
  "视图配置错误,请联系管理员": "ビュー設定エラーです。管理者に連絡してください",
  "找不到分组": "グループが見つかりません",
  "执行此操作后，流程将回滚到当前版本。您未发布的流程修改将会被清除，此操作无法撤回": "この操作を実行すると、プロセスは現在のバージョンまでロールバックされます。未公開の変更はすべて削除され、この操作は元に戻せません。",
  "索引字段的排序和你在视图中使用此字段参与排序的规则有关。当索引只有一个字段时，视图中排序的方向不会影响检索的加速；除此之外，请尽量保证在视图中的字段排序方式与索引中设置的一致，否则检索可能不会被加速。": "インデックスフィールドのソートは、このフィールドをビューでソートする際のルールに関連しています。インデックスにフィールドが1つだけある場合、ビュー内のソート方向は検索の高速化に影響しません。それに加えて、ビュー内のフィールドのソート方法がインデックスで設定したものと一致するように努めてください。そうでない場合、検索が高速化されない可能性があります。",
  "触发Webhook": "Webhookをトリガーする",
