  "选择索引字段时请记住一个原则：记录中重复值越少的字段，越适合建立索引。例如一个不允许重复的「商品编号」字段，就非常适合创建索引；反之，一个用于记录男、女的「性别」字段，则不适合创建索引。": "インデックスフィールドを選択する際には、1つの原則を念頭に置いてください。レコード内の重複値が少ないフィールドほど、インデックスの作成に適しています。例えば、重複を許可しない「商品番号」フィールドはインデックスを作成するのに非常に適しています。一方、男女を記録するための「性別」フィールドは、インデックスを作成するのには適していません。",
  "选择一组一对多关系的关联本表的“关联表”字段，数据将按照此字段的父级（单条）、子级（多条）关系来从左往右排列构成树状层级": "この表の「関連表」フィールドに関連する一対多の関係のセットを選択します。このフィールドの親（単一）および子（複数）関係に基づいて、データは左から右に木構造の階層として配置されます。",
  "当前尺寸下最大容纳%0行文字，字段内容超过1行后，默认向下换行直到完整显示。": "現在のサイズでは、最大 %0 行のテキストを収容できます。フィールドの内容が 1 行を超える場合、完全に表示されるまでデフォルトで下に折り返されます。",
