  "锁定后，导入的应用下所有用户不能查看、修改应用的配置，用户验证密码后可解锁其在应用下的操作权限。": "ロックされると、インポートされたアプリケーションの下にいるすべてのユーザーは、アプリケーションの設定を表示または変更できません。ユーザーは、パスワードを確認した後、アプリケーション内での操作権限を解除できます。",
  "将以当前的版本创建草稿。您当前正在编辑中的草稿和所有更新将会被删除，此操作无法撤回": "現在のバージョンで下書きが作成されます。現在編集中の下書きとすべての更新履歴は削除され、この操作は元に戻すことはできません。",
