  "暂无相关数据": "関連データはありません",
  "移动到自定义页面": "カスタムページに移動",
  "用户扩展信息表非常类似于组织中的用户管理表。在组织中，可以全局管理成员基础信息，如：部门、职位、组织角色等。其中部门、组织角色可用于数据权限范围，在工作表添加部门字段，可以使用户对自己所在部门的记录都拥有权限。同样在具体应用中，往往也需要额外管理用户在本应用中的扩展信息。如：销售管理应用中，需要管理销售人员所在的团队、区域、职能等，同时也希望这些信息可以类似部门一样用于数据权限范围。此时就可以建立一张销售人员表。": "ユーザー拡張情報テーブルは、組織内のユーザー管理テーブルと非常に似ています。組織内では、部門、職位、組織役割など、メンバーの基本情報をグローバルに管理できます。部門や組織役割はデータ権限の範囲に使用でき、ワークシートに部門フィールドを追加することで、ユーザーは自分が所属する部門のレコードに対する権限を持ちます。同様に、具体的なアプリケーションでは、ユーザーがこのアプリケーション内での拡張情報を追加管理する必要があることがよくあります。例えば、営業管理アプリケーションでは、営業担当者のチーム、地域、機能などを管理する必要があり、これらの情報が部門と同様にデータ権限の範囲に使用できることを望んでいます。この時、営業担当者テーブルを作成することができます。",
