  "注册开启审核后，审核结果(通过、拒绝)会邮件告知注册用户；外部门户类型设为私有后再添加用户后也会发送邀请通知，支持对邮件内容自定义。": "登録が承認された後、承認結果（承認、否認）は登録ユーザーにメールで通知されます。外部ポータルのタイプがプライベートに設定され、ユーザーを追加した後も招待通知が送信され、メール内容のカスタマイズがサポートされます。",
