  "批量复制": "バッチコピー",
  "权限标签指用于控制数据权限范围的扩展信息字段（仅支持关联类型字段）。当用户访问应用时，系统可以从扩展信息表中读取当前用户的权限标签，从而使用户对其他工作表中关联了相同标签的记录拥有权限。": "権限タグは、データアクセスの範囲を制御するための拡張情報フィールドです（関連型フィールドのみサポート）。ユーザーがアプリケーションにアクセスすると、システムは拡張情報テーブルから現在のユーザーの権限タグを読み取り、同じタグが関連付けられた他のワークシート内のレコードに対するアクセス権をユーザーに付与します。",
