  "已有账号": "アカウントをお持ちですか",
  "选择扩展信息表中作为用户权限标签的字段，仅支持关联记录类型的字段（最多可设置%0个字段）。当其他工作表的记录也关联了和用户相同的标签时，可以在角色中设置为用户对此记录拥有权限": "拡張情報ワークシートの中からユーザー権限ラベルとして使用するフィールドを選択します。関連レコードタイプのフィールドのみサポートされています（最大%0個のフィールドを設定可能）。他のワークシートのレコードがユーザーと同じラベルと関連付けられている場合、ロールでそのレコードに対するユーザーの権限を設定できます。",
