  "如：还是在销售管理应用中，用户扩展信息表中已设置了团队作为用户权限标签（关联团队表），并且订单表也关联了所属团队时。那么当用户访问应用时，系统就可以根据读取到的用户所在团队，并从订单表中过滤出关联了相同团队的订单，从而实现用户对属于自己团队的订单拥有查看、编辑或删除权限（可以在角色权限中进行设置）。": "例えば、営業管理アプリケーションにおいてユーザーの拡張情報表でチームがユーザー権限ラベル（チーム表に関連付け）として設定されており、注文表も所属チームに関連付けられている場合、ユーザーがアプリケーションにアクセスすると、システムは読み取ったユーザーの所属チームに基づいて、注文表から同じチームに関連する注文をフィルタリングすることができるため、ユーザーは自分のチームに属する注文に対する表示、編集、削除の権限を持つ（これは役割権限で設定できます）。",
