  "7.明道云用户必须防范和抵制制作、复制、发布含有下列内容的不良信息：使用夸张标题，内容与标题严重不符的；炒作绯闻、丑闻、劣迹等的；不当评述自然灾害、重大事故等灾难的；带有性暗示、性挑逗等易使人产生性联想的；展现血腥、惊悚、残忍等致人身心不适的；煽动人群歧视、地域歧视等的；宣扬低俗、庸俗、媚俗内容的；可能引发未成年人模仿不安全行为和违反社会公德行为、诱导未成年人不良嗜好等的；其他对网络生态造成不良影响的内容。": "7.明道云のユーザーは、次の内容を含む有害な情報の制作、複製、公開を防止し、抵抗する必要があります：誇張されたタイトルを使用し、内容がタイトルと大きく一致しないもの；スキャンダルや噂、悪行を煽るもの；自然災害や重大事故などの災害について不適切に言及するもの；性的暗示や挑発を含み、人々に性的連想を引き起こす可能性があるもの；血なまぐさい、恐怖を感じさせる、残酷な内容を示すもので、身体的または精神的な不快感を引き起こすもの；集団差別や地域差別を煽動するもの；低俗で安っぽくて俗的な内容を宣伝するもの；未成年者が危険な行動を模倣したり、社会的モラルに反する行動を取ったり、未成年者の悪習を誘発したりする可能性のあるもの；およびネットワークエコシステムに悪影響を及ぼす他のすべての内容。",
