  "8.明道云账户一旦被注销将不可恢复，请明道云用户在操作之前自行备份账户相关的所有信息和数据。注销明道云账户，明道云用户将无法再使用本明道云账户，也将无法找回用户的明道云账户中及与账户相关的任何内容或信息（即使使用相同的手机号码再次注册并使用明道云软件），包括但不限于：": "8.明道雲アカウントは一度キャンセルされると、復元できません。 明道雲ユーザーは、アカウントに関連するすべての情報およびデータをバックアップしてから手続きを行うことをお勧めします。明道雲アカウントをキャンセルすると、明道雲ユーザーはこの明道雲アカウントを使用できなくなり、ユーザーの明道雲アカウント内および関連するコンテンツまたは情報（同じ携帯電話番号を使用して明道雲ソフトウェアを再度登録および使用する場合でも）を取得することができなくなりますが、これらに限定されません。",
