  "如果就本协议的解释或执行发生争议，双方应首先力争通过友好协商解决该争议。如果在一方向其他方送达要求开始协商的书面通知后六十天内未能通过协商解决争议，那么任何一方均可将争议提交至中国国际经济贸易仲裁委员会上海分会，按照其届时有效的规则进行仲裁。仲裁裁决是终局的，对各方均有约束力，不可上诉。仲裁费用由败诉方承担，除非仲裁裁决另有规定。当任何争议发生时以及在对任何争议进行仲裁时，除争议事项外，各方应继续行使各自在本协议项下的其他权利，履行各自在本协议项下的其他义务。": "本契約の解釈または実行に関して紛争が生じた場合、両当事者はまず友好的な協議を通じてその紛争を解決するよう努めるものとします。一方が他方に協議を開始する旨の書面通知を送付してから60日以内に協議によって紛争が解決できない場合、いずれの当事者も中国国際経済貿易仲裁委員会上海支部に紛争を提出し、当時有効な規則に従って仲裁を行うことができます。仲裁の裁定は最終的であり、両当事者を拘束し、控訴することはできません。仲裁費用は敗訴した方が負担し、仲裁の裁定に別段の定めがない限り、これに従います。紛争が発生した場合及びいかなる紛争が仲裁に付される場合、紛争事項を除き、両当事者は本契約に基づく他の権利を行使し、他の義務を履行し続けなければなりません。",
