  "3.在发生需要从备份文件中恢复数据的情形时，明道云通常需要4小时，最长48小时完成，在此时间范围内的数据恢复视作服务是连续的。": "3.バックアップファイルからデータを復元する必要がある場合、明道雲は通常4時間、最大48時間で完了します。この時間範囲内のデータ復元は、継続的なサービスと見なされます。",
  "支持 jpg、jpeg、png、gif格式，2MB以内": "jpg、jpeg、png、gif形式に対応、2MB以内",
  "1.明道云将尽最大努力保障软件平台的连续可靠运行，对付费版用户，明道云承诺99%以上的正常在线率，低于此比例，明道云有义务按照服务中断时间比例向客户退还相应的服务费用，客户理解该等赔偿。明道云对免费模式用户不提供任何补偿。": "1. 明道雲は、ソフトウェアプラットフォームの継続的で信頼できる運用を最大限に努力して保障します。有料版ユーザーに対して、明道雲は99%以上の稼働率を約束します。この割合を下回る場合、明道雲はサービス中断時間に基づいて顧客に相応のサービス料金の返金を義務付けられます。顧客はその賠償を理解しています。明道雲は無料モデルのユーザーには何らかの補償を提供しません。",
  "知识中心": "知識センター",
  "4.本使用协议依据国家相关法律法规规章制定，明道云用户同意严格遵守以下义务：（1）不得利用明道云产品从事洗钱、窃取商业秘密、窃取个人信息等违法犯罪活动；（2）不得干扰明道云产品的正常运转，不得明道云产品及国家计算机信息系统；（3）不得传输或发表任何违法犯罪的、骚扰性的、中伤他人的、辱骂性的、恐吓性的、伤害性的、庸俗的、不文明的等信息；（4）不得教唆他人从事违法违规或本使用协议所禁止的行为；（5）不得利用在明道云注册的账户买卖进行牟利性经营活动；（6）不得发布任何侵犯他人个人信息、著作权、商标权等知识产权或合法权利的内容；": "4.本使用契約は、国家の関連法令および規則に基づいて作成されており、明道云のユーザーは以下の義務を厳守することに同意します：（1）明道云の製品を利用してマネーロンダリング、営業秘密の窃盗、個人情報の窃盗等の違法犯罪行為を行ってはなりません；（2）明道云の製品の正常な運営を妨害してはならず、明道云の製品および国家のコンピュータ情報システムに対しても妨害を行ってはなりません；（3）違法犯罪の情報、嫌がらせの情報、他人を中傷する情報、侮辱的な情報、脅迫的な情報、有害な情報、卑俗な情報、非文明的な情報などを送信または発表してはなりません；（4）他者に対して違法または禁止されている行為を煽動してはなりません；（5）明道云に登録されたアカウントを利用して営業を行い、利益を得てはなりません；（6）他人の個人情報、著作権、商標権などの知的財産権または法的権利を侵害する内容を発表してはなりません。",
