  "5.在法律允许的范围内，明道云对因：（1）明道云产品受到计算机病毒、木马或其他恶意程序、黑客攻击的破坏；（2）明道云用户操作不当或用户通过非明道云授权的方式使用本服务；（3）程序版本过时、设备的老化和/或其兼容性问题；（4）其他明道云无法控制或合理预见的情形，导致的明道云服务中断或终止，不承担赔偿责任。": "5. 法律で許可されている範囲内で、明道雲は以下の理由によって生じる損害について責任を負いません：（1）明道雲製品がコンピュータウイルス、トロイの木馬、またはその他の悪意のあるプログラムやハッカー攻撃により破壊された場合；（2）明道雲ユーザーの不適切な操作またはユーザーが明道雲の許可なく本サービスを使用した場合；（3）プログラムバージョンの古さ、デバイスの老朽化および/またはその互換性の問題；（4）明道雲が制御または合理的に予見できないその他の状況により、明道雲サービスが中断または終了した場合。",
