  "1.本协议是明道云用户（包括使用的个人和代表的企业）与明道云运营企业上海万企明道软件有限公司之间的协议，用户注册明道云服务即代表接受本协议的约束，并自注册成功之时即成为本协议一方，付费版用户签署本协议并回传（包括使用传真，电子邮件等电子通信手段）给明道云即代表接受本协议中的计费和支付协议，并自发出协议之时即受该等协议约束。": "1.本契約は、明道雲のユーザー（利用する個人および代表する企業を含む）と明道雲の運営企業である上海万企明道ソフトウェア有限公司との間の契約です。ユーザーが明道雲サービスに登録することにより、本契約の拘束を受け入れることを表明し、登録が成功した時点で本契約の一方となります。有料プランのユーザーが本契約に署名し、明道雲に（ファックス、電子メールなどの電子通信手段を使用して）返送することで、本契約に記載された請求および支払い契約を受け入れたこととみなされ、契約が送信された時点からその契約の拘束を受けます。",
