  "下文中的“明道云”指应用平台“明道云”（包括但不限于明道云网页、明道云App以及明道云微信小程序）或其运营企业上海万企明道软件有限公司，也是本协议的契约方之一。": "以下の文中の「明道雲」は、アプリケーションプラットフォーム「明道雲」（明道雲ウェブサイト、明道雲アプリ、明道雲微信ミニプログラムを含むがこれに限定されない）またはその運営企業である上海万企明道ソフトウェア株式会社を指し、本契約の契約当事者の一つでもあります。",
  "2.明道云使用客户所拥有的手机号作为用户权证的唯一识别信息。当客户不再拥有在明道云登记的手机号时，明道云有权终止提供服务，客户亦可以通过变更手机号的方式继续使用明道云服务。在付费版下，系统支持多个域名电子邮件地址，当最早登记的主域名权属发生改变时，明道云有权终止提供服务。": "2. 明道雲は、顧客が所有する携帯電話番号をユーザー権証の唯一の識別情報として使用します。顧客が明道雲に登録された携帯電話番号をもはや所有しない場合、明道雲はサービス提供を終了する権利を有し、顧客は電話番号を変更することで引き続き明道雲サービスを利用することができます。有料版では、システムは複数のドメイン電子メールアドレスをサポートしており、最初に登録された主ドメインの所有権が変更された場合、明道雲はサービスを終了する権利を有します。",
