  "3)通过明道云账号进行登录的明道云旗下APP（包括但不限于明道云APP等）所有记录都将无法找回。无法再登录、使用前述服务，曾获得的SaaS服务、外部用户包、工作流执行行数付费包、应用附件上传量扩充包等视为自行放弃，将无法继续使用。明道云用户应当理解并同意，明道云无法协助重新恢复前述服务。": "3）MingdaoアカウントでログインしたMingdaoアプリ（Mingdaoアプリに限定されません）のすべてのレコードは復元できません。ユーザーは、上記のサービスにログインしたり利用したりすることができなくなります。また、これまで取得したSaaSサービス、外部ユーザーパッケージ、ワークフロー実行数サブスクリプションパッケージ、アプリケーション添付ファイルアップロード容量拡張パッケージなども、ユーザー自身が放棄したものとみなされ、継続利用はできません。Mingdaoユーザーは、Mingdaoがこれらのサービス復旧を支援できないことを理解し、同意してください。",
