  "客户应当按照本订单载明的支付义务及时支付价款，用户逾期支付账单超过30天后系统会停止高级模式服务，而转入免费模式，用户在高级模式下的设定参数数据可能因此丢失或恢复缺省设置。即使在停止高级模式服务后，任何未支付的账单均会作为客户的欠款，明道云保留追讨欠款及滞纳金的权利，滞纳金将根据拖欠天数，每天按欠款金额的万分之五计收。": "顧客は本注文書に記載された支払い義務に従って、適時に料金を支払わなければなりません。ユーザーが請求書の支払いを30日以上遅延した場合、システムはプレミアムモードサービスを停止し、無料モードに移行します。プレミアムモードで設定したパラメータデータは、このことにより失われるか、デフォルト設定に戻される可能性があります。プレミアムモードサービスが停止された後も、未払いの請求書はすべて顧客の負債と見なされます。明道雲は、負債および延滞料金を請求する権利を留保しており、延滞料金は延滞日数に応じて、未払い金額の0.05%を毎日請求します。",
