  "6.明道云用户不得制作、传输或发表以下违法信息：反对宪法所确定的基本原则的；危害国家安全，泄露国家秘密，颠覆国家政权，破坏国家统一的；损害国家荣誉和利益的；歪曲、丑化、亵渎、否定英雄烈士事迹和精神，以侮辱、诽谤或者其他方式侵害英雄烈士的姓名、肖像、名誉、荣誉的；宣扬恐怖主义、极端主义或者煽动实施恐怖活动、极端主义活动的；煽动民族仇恨、民族歧视，破坏民族团结的；破坏国家宗教政策，宣扬邪教和封建迷信的；散布谣言，扰乱经济秩序和社会秩序的；散布淫秽、色情、赌博、暴力、凶杀、恐怖或者教唆犯罪的；侮辱或者诽谤他人，侵害他人名誉、隐私和其他合法权益的；法律、行政法规禁止的其他内容。": "6.明道雲利用者は、憲法の定める基本原則に反し、国家の安全を脅かし、国家機密を漏洩し、国家権力を破壊し、国民統合を損ない、国家の名誉と利益を毀損し、英雄烈士の行為と精神を歪曲、スキャンダル、冒涜、否定し、英雄烈士の名前、肖像、名誉を侮辱、中傷、その他侵害する違法情報を作成、送信、公表してはなりません。テロリズム、過激派を助長し、またはテロリズム、過激派活動を扇動する行為、民族憎悪、民族差別を扇動し、国民統合を損なう行為、国家の宗教政策を損ない、邪教や封建的迷信を助長する行為、経済・社会秩序を乱す噂を流す行為、わいせつ、ポルノ、賭博、暴力、殺人、テロ、犯罪幇助を広げる行為、他人を侮辱・中傷してその権利を侵害する行為などがこれにあたるとされています。その他、法令で禁止されている内容。",
