  "4.如因用户违反本协议、法律法规要求、用户未能履行付款义务或用户注销账户等造成数据丢失、删除、毁损的，明道云不承担任何责任，用户应自行负责对数据进行备份。": "4. ユーザーが本契約、法律、規則を違反した場合、ユーザーが支払い義務を履行できなかった場合、またはアカウントを取消した場合にデータの喪失、削除、破損が発生した場合、Mingdao Cloud は一切の責任を負わず、ユーザーは自己の責任でデータのバックアップを行うものとします。",
