  "5.除非法律允许或本公司书面许可，使用明道云产品过程中不得从事下列行为：（1）删除明道云产品及其副本上关于著作权的信息；（2）对明道云产品进行反向工程、反向汇编、反向编译，或者以其他方式尝试发现明道云产品的源代码；（3）对明道云拥有知识产权的内容进行使用、出租、出借、复制、修改、链接、转载、汇编、发表、出版、建立镜像站点等；（4）对明道云产品或其运行过程中释放到任何终端内存中的数据、运行过程中客户端与服务器端的交互数据，以及明道云产品运行所必需的系统数据，进行复制、修改、增加、删除、挂接运行或创作任何衍生作品，形式包括但不限于使用插件、外挂或非经明道云授权的第三方工具/服务接入明道云产品和相关系统；（5）通过修改或伪造明道云产品运行中的指令、数据，增加、删减、变动明道云产品的功能或运行效果，或者将用于上述用途的软件、方法进行运营或向公众传播，无论这些行为是否为商业目的；（6）通过非明道云开发、授权的第三方软件、插件、外挂、系统，登录或使用明道云产品及服务，或制作、发布、传播上述工具；（7）自行或者授权他人、第三方软件对明道云产品及其组件、模块、数据进行干扰。": "5.(3) 明道雲が知的財産権を有するコンテンツの使用、賃貸、貸与、コピー、修正、リンク、複製、編集、出版、ミラーサイトの開設など (4) 明道雲製品またはその運用過程で端末のメモリに解放されたデータ、その運用過程でクライアントとサーバー間の相互作用データ、明道雲製品の運用に必要なシステムデータなどのコピー、修正、追加、削除、フックアップ、ラン、派生物の作成。(5)明道雲製品および関連システムにアクセスするために、プラグイン、プラグインまたは明道雲が決裁していない第三者のツール/サービスを使用することを含みますが、これに限定されません。(6)明道雲製品の操作における指示およびデータを修正または改竄して、明道クラウド製品の機能または操作効果を追加、削除、変更したり、上記の目的で使用したソフトウェアまたは方法を操作または公衆に広める行為、これらの行為が商業目的であるかどうかに関わらず。(6) 明道雲が開発または認可していない第三者のソフトウェア、プラグイン、プラグインまたはシステムを通じて明大クラウド製品およびサービスをログインまたは使用すること、または上記のツールを作成、公開または普及させること (7) 明道雲製品およびそのコンポーネント、モジュール、データに対して自らまたは他人もしくは第三者のソフトウェアを認可して干渉すること。",
