  "2.客户应当按照本订单载明的支付义务及时支付价款，用户逾期支付账单超过30天后系统会停止付费版服务，而转入免费模式，用户在付费版下的设定参数数据可能因此丢失或恢复缺省设置。即使在停止付费版服务后，任何未支付的账单均会作为客户的欠款，明道云保留追讨欠款及滞纳金的权利，滞纳金将根据拖欠天数，每天按欠款金额的万分之五计收。": "2. 顧客は、本注文に記載された支払い義務に従って、適時に代金を支払うものとします。ユーザーが請求書の支払いを30日以上遅延した場合、システムは有料版サービスを停止し、無料モードに切り替えます。有料版における設定パラメータデータは、これにより失われる可能性があり、初期設定に戻されることがあります。有料版サービスを停止した後も、未払いの請求書は顧客の債務と見なされます。明道雲は、債務および延滞料金を回収する権利を留保し、延滞料金は、遅延日数に応じて、未払い金額の0.05%が毎日計算されます。",
  "为您的成员安装App（支持IOS或者Andriod)": "メンバーのためにアプリをインストールします（iOSまたはAndroidをサポート）",
  "根据字段名的拼音自动生成别名，若字段名为英文则直接取字段名作为别名，此操作不会影响已设置的别名。": "フィールド名のピンインに基づいてエイリアスを自動生成します。フィールド名が英語の場合、エイリアスはフィールド名と同じになります。この操作は、既に設定されたエイリアスに影響を与えません。",
  "完整显示": "完全表示",
