  "在向用户提供服务的过程中，明道云可能会接入第三方的产品或服务，该产品或服务由明道云以外的第三方提供。在法律允许的范围内，明道云不对第三方的产品或服务承担任何责任。用户需遵守所有第三方的产品或服务的使用条款和隐私政策。": "ユーザーにサービスを提供する過程で、明道雲は第三者の製品やサービスを統合する場合があります。この製品やサービスは明道雲以外の第三者によって提供されます。法律が許す範囲内で、明道雲は第三者の製品やサービスについて一切責任を負いません。ユーザーは、すべての第三者の製品やサービスの利用規約およびプライバシーポリシーを遵守する必要があります。",
  "电子邮箱": "メールアドレス",
