  "通过设置工作表和字段别名，使得它们在API、webhook、自定义打印等场景使用的时候更具有辨识度。": "ワークシートとフィールドのエイリアスを設定することで、API、Webhook、カスタム印刷などのシーンで使用されるときに、より認識しやすくなります。",
  "3.明道云保留面向免费模式用户刊载广告的权利，这些广告刊载过程中将可能使用必要的定向技术来提高广告相关度，但明道云不会将用户的个人信息透露给广告商，而只会在匿名的基础上通过自动化匹配技术实现广告优化刊载。": "3. 明道雲は、無料モデルユーザーに広告を掲載する権利を保留します。広告掲載の過程で、広告の関連性を高めるために必要なターゲティング技術が使用される可能性がありますが、明道雲はユーザーの個人情報を広告主に開示せず、匿名の基盤の上で自動マッチング技術を通じて広告最適化を実現します。",
