  "1.服务将按照“现状”和“可得到”的状态提供。明道云在此明确声明，除本协议有明确约定外，明道云对服务不作任何明示或暗示的保证，包括但不限于对服务的适用性、准确性、持续性、可靠性、服务没有错误或疏漏等。": "1. サービスは「現状のまま」および「利用可能な範囲」で提供されます。明道雲はここに明示的に、当該合意に明示的に定められたことを除き、サービスに関して明示的または暗示的な保証を行わないことを明言します。これには、サービスの適用性、正確性、継続性、信頼性、エラーや不備がないことが含まれます。",
  "当前记录无权限，无法查看": "現在のレコードを表示する権限がありません",
  "取消关联(%0)": "リンク解除 (%0)",
  "可根据配置的打印模板将记录转为PDF、Word或Excel文件，可以通过新增记录、更新记录或发送邮件节点将文件写入附件": "設定された印刷テンプレートに基づいて、レコードをPDF、Word、またはExcelファイルに変換できます。新しいレコード、更新されたレコード、またはメール送信ノードを通じてファイルを添付ファイルに書き込むことができます。",
  "时区为beta功能，仅适用于工作表中日期时间类型的日期字段和系统字段。您可以设置个人时区，便于您录入和查看时间数据。例如，您在东京时，可以将个人时区设置为东九时区(UTC+9:00)。你输入的时间被平台视作东京时间，同时，工作表中的日期时间数据以东京时间呈现。": "タイムゾーンはベータ機能で、ワークシートの日付/時刻タイプのフィールドとシステムフィールドにのみ適用されます。個人のタイムゾーンを設定することで、時間データの入力と表示が容易になります。たとえば、東京にいるときは、個人のタイムゾーンをUTC+9:00に設定できます。入力した時間はプラットフォームによって東京時間として扱われ、ワークシートの日付/時刻データも東京時間で表示されます。",
