  "对高级模式用户，明道云承诺提供服务期内99%的正常服务率，因产品更新而预先通知的小于一小时的停机维护应当视作正常服务范围。在发生需要从备份文件中恢复数据的情形时，明道云通常需要4小时，最长48小时完成，在此时间范围内的数据恢复视作服务是连续的。": "高級モードのユーザーに対して、明道雲はサービス期間中に99%の正常稼働率を提供することを約束します。製品の更新による事前通知が1時間未満のダウンタイム保守は、通常のサービス範囲内と見なされます。バックアップファイルからデータを復元する必要がある場合、明道雲は通常4時間、最長48時間を要し、この時間範囲内のデータ復元は継続的なサービスと見なされます。",
