  "1. 复制你需要的字段代码然后粘贴到您本地 Word 模板（只支持docx格式）或 Excel 模板（只支持xlsx格式）中相应的位置，打印时会获取实际数据中该字段填写的内容。": "1. 必要なフィールドコードをコピーし、ローカルのWordテンプレート（docx形式のみサポート）またはExcelテンプレート（xlsx形式のみサポート）の対応する位置に貼り付けます。印刷時には、そのフィールドに入力された実際のデータが取得されます。",
  "未勾选时，表示统计从本年1月1日开始到12月31日的数据，勾选时，表示统计从本年1月1日开始到今天的数据。": "チェックされていない場合は、今年の1月1日から12月31日までのデータを集計することを意味し、チェックされている場合は、今年の1月1日から今日までのデータを集計することを意味します。",
