  "（1）图片尺寸支持4种设置方式。[90*auto] 表示宽度固定为90，高度自适应。[auto*90] 表示宽度自适应，高度固定为90。[90*50_auto]表示宽高在90*50的范围内同时自适应。[90*50]表示宽高为固定尺寸。": "（1）画像サイズは4種類の設定方式をサポートしています。[90*auto]は幅が90で、高さが自動的に調整されることを示します。[auto*90]は幅が自動的に調整され、高さが90に固定されていることを示します。[90*50_auto]は幅と高さが90*50の範囲内で同時に自動調整されることを示します。[90*50]は幅と高さが固定されたサイズであることを示します。",
